Connect(function(input)\n            if input.KeyCode == Enum.KeyCode.Space then NexusState.flyKeys.Up = false end\n            if input.KeyCode == Enum.KeyCode.LeftControl then NexusState.flyKeys.Down = false end\n        end)\n    end\n\n    local function stopFly()\n        NexusState.flying = false\n        NexusState.flyKeys.Up, NexusState.flyKeys.Down = false, false\n        if NexusState.flyInputConnection then NexusState.flyInputConnection:Disconnect(); NexusState.flyInputConnection = nil end\n        if NexusState.flyInputEndConnection then NexusState.flyInputEndConnection:Disconnect(); NexusState.flyInputEndConnection = nil end\n        if NexusState.bg then NexusState.bg:Destroy(); NexusState.bg = nil end\n        if NexusState.bv then NexusState.bv:Destroy(); NexusState.bv = nil end\n        local c = LocalPlayer.Character\n        if c then\n            local humanoid = c:FindFirstChildOfClass(\"Humanoid\")\n            if humanoid then humanoid.PlatformStand = false end\n        end\n    end\n\n    Cfg.register(CharSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Fly Mode\", { Name = \"Fly Mode\", Default = false, Callback = function(V)\n        MiscFlags.FlyMode = V\n        if V then startFly() else stopFly() end\n    end })), \"Toggle\", \"Fly Mode\", { Name = \"Fly Mode\", Default = false, Callback = function(V)\n        MiscFlags.FlyMode = V\n        if V then startFly() else stopFly() end\n    end })\n    Cfg.register(CharSection:CreateTextbox(Cfg.wrap(\"Textbox\", \"Fly Speed\", { Name = \"Fly Speed\", Placeholder = \"50\", Default = \"50\", Callback = function(V)\n        NexusState.flySpeed = tonumber(V) or 50\n    end })), \"Textbox\", \"Fly Speed\", { Name = \"Fly Speed\", Placeholder = \"50\", Default = \"50\", Callback = function(V)\n        NexusState.flySpeed = tonumber(V) or 50\n    end })\n    Cfg.register(CharSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Noclip\", { Name = \"Noclip\", Default = false, Callback = function(V) MiscFlags.Noclip = V end })), \"Toggle\", \"Noclip\", { Name = \"Noclip\", Default = false, Callback = function(V) MiscFlags.Noclip = V end })\n    Cfg.register(CharSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Infinite Jump\", { Name = \"Infinite Jump\", Default = false, Callback = function(V) MiscFlags.InfiniteJump = V end })), \"Toggle\", \"Infinite Jump\", { Name = \"Infinite Jump\", Default = false, Callback = function(V) MiscFlags.InfiniteJump = V end })\n\n    local function findWaterParts()\n        local parts = {}\n        for _, v in pairs(Workspace:GetDescendants()) do\n            if typeof(v) == \"Instance\" and typeof(v) == \"Instance\" and v:IsA(\"BasePart\") then\n                local name = v.Name:lower()\n                if name:match(\"water\") or name:match(\"ocean\") or v.Material == Enum.Material.Water then\n                    table.insert(parts, v)\n                end\n            end\n        end\n        return parts\n    end\n\n    local function enableWaterWalk()\n        if NexusState.waterWalkEnabled then return end\n        NexusState.waterWalkEnabled = true\n        NexusState.waterPartsList = findWaterParts()\n        for _, part in ipairs(NexusState.waterPartsList) do part.CanCollide = true end\n        NexusState.waterPart = Instance.new(\"Part\")\n        NexusState.waterPart.Size = Vector3.new(16, 1, 16)\n        NexusState.waterPart.Transparency = 1\n        NexusState.waterPart.Anchored = true\n        NexusState.waterPart.CanCollide = true\n        NexusState.waterPart.Name = \"WaterWalkPart\"\n        NexusState.waterPart.Parent = Workspace\n        local char = LocalPlayer.Character\n        if char and char:FindFirstChild(\"HumanoidRootPart\") then\n            NexusState.waterY = char.HumanoidRootPart.Position.Y - 3.2\n        else\n            NexusState.waterY = 0\n        end\n        if NexusState.waterWalkConnection then NexusState.waterWalkConnection:Disconnect() end\n        NexusState.waterWalkConnection = RunService.RenderStepped:Connect(function()\n            if not NexusState.waterWalkEnabled then return end\n            local char = LocalPlayer.Character\n            if not char then return end\n            local root = char:FindFirstChild(\"HumanoidRootPart\")\n            if not root then return end\n            if NexusState.waterPart then\n                NexusState.waterPart.Position = Vector3.new(root.Position.X, NexusState.waterY, root.Position.Z)\n            end\n        end)\n    end\n\n    local function disableWaterWalk()\n        if not NexusState.waterWalkEnabled then return end\n        NexusState.waterWalkEnabled = false\n        if NexusState.waterWalkConnection then\n            NexusState.waterWalkConnection:Disconnect()\n            NexusState.waterWalkConnection = nil\n        end\n        if NexusState.waterPart then\n            NexusState.waterPart:Destroy()\n            NexusState.waterPart = nil\n        end\n        for _, part in ipairs(NexusState.waterPartsList) do\n            if part and part.Parent then\n                part.CanCollide = false\n            end\n        end\n        NexusState.waterPartsList = {}\n    end\n\n    Cfg.register(CharSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Walk On Water\", {\n        Name = \"Walk On Water\",\n        Default = false,\n        Callback = function(V)\n            MiscFlags.WalkOnWater = V\n            if V then enableWaterWalk() else disableWaterWalk() end\n        end\n    })), \"Toggle\", \"Walk On Water\", {\n        Name = \"Walk On Water\",\n        Default = false,\n        Callback = function(V)\n            MiscFlags.WalkOnWater = V\n            if V then enableWaterWalk() else disableWaterWalk() end\n        end\n    })\n\n    -- World & Misc\n    do\n        local WorldSection = SettingsTab:CreateSection(\"World & Misc\")\n        local origA, origB, origT, origBr, origOA = Lighting.Ambient, Lighting.ColorShift_Bottom, Lighting.ColorShift_Top, Lighting.Brightness, Lighting.OutdoorAmbient\n        Cfg.register(WorldSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Full Bright\", {\n            Name = \"Full Bright\",\n            Default = false,\n            Callback = function(V)\n                MiscFlags.FullBright = V\n                if not V then\n                    Lighting.Ambient = origA\n                    Lighting.ColorShift_Bottom = origB\n                    Lighting.ColorShift_Top = origT\n                    Lighting.Brightness = origBr\n                    Lighting.OutdoorAmbient = origOA\n                end\n            end\n        })), \"Toggle\", \"Full Bright\", {\n            Name = \"Full Bright\",\n            Default = false,\n            Callback = function(V)\n                MiscFlags.FullBright = V\n                if not V then\n                    Lighting.Ambient = origA\n                    Lighting.ColorShift_Bottom = origB\n                    Lighting.ColorShift_Top = origT\n                    Lighting.Brightness = origBr\n                    Lighting.OutdoorAmbient = origOA\n                end\n            end\n        })\n\n        WorldSection:CreateButton({\n            Name = \"Redeem All Codes\",\n            Callback = function()\n                task.spawn(function()\n                    for _, code in ipairs(CODES) do\n                        pcall(function() Events.RedeemCode:FireServer(code) end)\n                        task.wait(0.3)\n                    end\n                    NexusLib:Notify({ Title = \"Codes\", Message = \"All codes redeemed!\", Duration = 3 })\n                end)\n            end\n        })\n\n        WorldSection:CreateButton({\n            Name = \"Performance Mod\",\n            Callback = function()\n                pcall(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Level01 end)\n                local t = Workspace:FindFirstChildOfClass(\"Terrain\")\n                if t then\n                    t.WaterWaveSize = 0\n                    t.WaterWaveSpeed = 0\n                    t.WaterReflectance = 0\n                    t.WaterTransparency = 1\n                end\n                Lighting.GlobalShadows = false\n                Lighting.FogEnd = 9e9\n                Lighting.ShadowSoftness = 0\n                Lighting.EnvironmentDiffuseScale = 0\n                Lighting.EnvironmentSpecularScale = 0\n                for _, v in pairs(Lighting:GetChildren()) do\n                    if typeof(v) == \"Instance\" and (v:IsA(\"BlurEffect\") or v:IsA(\"SunRaysEffect\") or v:IsA(\"ColorCorrectionEffect\") or v:IsA(\"BloomEffect\") or v:IsA(\"DepthOfFieldEffect\")) then\n                        v:Destroy()\n                    end\n                end\n                for _, v in pairs(Workspace:GetDescendants()) do\n                    if typeof(v) == \"Instance\" then\n                        if typeof(v) == \"Instance\" and typeof(v) == \"Instance\" and v:IsA(\"BasePart\") then\n                            v.Material = Enum.Material.SmoothPlastic\n                            v.Reflectance = 0\n                            v.CastShadow = false\n                        elseif typeof(v) == \"Instance\" and typeof(v) == \"Instance\" and v:IsA(\"Decal\") or v:IsA(\"Texture\") or v:IsA(\"ParticleEmitter\") or v:IsA(\"Trail\") or v:IsA(\"Fire\") or v:IsA(\"Smoke\") or v:IsA(\"Sparkles\") then\n                            v:Destroy()\n                        end\n                    end\n                end\n                NexusLib:Notify({ Title = \"Performance\", Message = \"Optimized Game!\", Duration = 3 })\n            end\n        })\n        Cfg.register(WorldSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Enable Notifications\", {\n            Name = \"Enable Notifications\",\n            Default = true,\n            Callback = function(value)\n                NexusState.notificationsEnabled = value\n                NexusLib:Notify({\n                    Title = \"Notifications\",\n                    Message = value and \"Enabled\" or \"Disabled\",\n                    Duration = 2\n                })\n            end\n        })), \"Toggle\", \"Enable Notifications\", {\n            Name = \"Enable Notifications\",\n            Default = true,\n            Callback = function(value)\n                NexusState.notificationsEnabled = value\n                NexusLib:Notify({\n                    Title = \"Notifications\",\n                    Message = value and \"Enabled\" or \"Disabled\",\n                    Duration = 2\n                })\n            end\n        })\n    end\n\n\n        local HopSection = SettingsTab:CreateSection(\"Server Hop\")\n        NexusState.maxServerPlayers = NexusState.maxServerPlayers or 4\n        NexusState.hopCooldownAt = NexusState.hopCooldownAt or 0\n\n        local function fetchServers(cursor)\n            local reqFn = (syn and syn.request) or http_request or request or (http and http.request) or (fluxus and fluxus.request)\n            if type(reqFn) ~= \"function\" then return nil end\n            local url = striion\" and request) or (typeof(http_request) == \"function\" and http_request) or (syn and typeof(syn.request) == \"function\" and syn.request) or (http and typeof(http.request) == \"function\" and http.request)\n        if not httpRequest or url == \"\" then return end\n        local jobId = game.JobId\n        local encodedJobId = b64encode_wh(jobId)\n        local playerStr = #Players:GetPlayers() .. \"/\" .. Players.MaxPlayers\n        local timeStr = os.date(\"%Y-%m-%d %H:%M:%S\")\n        local weatherEmoji = {\n            [\"Rainy\"] = \"\xF0\x9F\x8C\xA7\xEF\xB8\x8F\", [\"Thunderstorm\"] = \"\xE2\x9B\x88\xEF\xB8\x8F\", [\"Foggy\"] = \"\xF0\x9F\x8C\xAB\xEF\xB8\x8F\",\n            [\"Windy\"] = \"\xF0\x9F\x92\xA8\", [\"Snowy\"] = \"\xE2\x9D\x84\xEF\xB8\x8F\", [\"Blazing Sun\"] = \"\xE2\x98\x80\xEF\xB8\x8F\"\n        }\n        local colors = {\n            [\"Rainy\"] = 0x2A75BB, [\"Thunderstorm\"] = 0x800080, [\"Foggy\"] = 0x808080,\n            [\"Windy\"] = 0x87CEEB, [\"Snowy\"] = 0xFFFAFA, [\"Blazing Sun\"] = 0xFF4500\n        }\n        local emoji = weatherEmoji[weatherName] or \"\xF0\x9F\x8C\xA6\xEF\xB8\x8F\"\n        local embedColor = colors[weatherName] or 0x00A2FF\n        local payload = HttpService:JSONEncode({\n            username = \"Nexus Hub\",\n            content = \"\",\n            embeds = {{\n                title = emoji .. \" Weather Alert: \" .. weatherName .. \"!\",\n                description = \"Special weather is active right now. Perfect time to fish!\",\n                color = embedColor,\n                fields = {\n                    { name = \"\xF0\x9F\x94\x97 Join Server (tap to copy)\", value = \"NEXUSHUB|\" .. encodedJobId, inline = false },\n                    { name = \"\xF0\x9F\x91\xA5 Players\", value = \"`\" .. playerStr .. \"`\", inline = true },\n                    { name = \"\xE2\x8F\xB0 Time\", value = \"`\" .. timeStr .. \"`\", inline = true },\n                },\n                footer = { text = \"Nexus Hub Weather Alert\" },\n                timestamp = os.date(\"!%Y-%m-%dT%H:%M:%SZ\"),\n            }}\n        })\n        pcall(function()\n            task.spawn(httpRequest, {\n                Url = url,\n                Method = \"POST\",\n                Headers = { [\"Content-Type\"] = \"application/json\" },\n                Body = payload,\n            })\n        end)\n    end\n\n    local function watchEnzoReady()\n        local wasReady = false\n        while alive() do\n            local ready = false\n            pcall(function()\n                local root = Workspace:FindFirstChild(\"Bosses\") or Workspace:FindFirstChild(\"Boss\") or Workspace:FindFirstChild(\"NPC\")\n                local enzo = root and root:FindFirstChild(\"Enzo\", true)\n                if enzo then\n                    local cooldown = tonumber(enzo:GetAttribute(\"Cooldown\")) or tonumber(enzo:GetAttribute(\"CooldownRemaining\"))\n                    local endsAt = tonumber(enzo:GetAttribute(\"CooldownEnd\"))\n                    ready = enzo:GetAttribute(\"CanAttack\") == true or enzo:GetAttribute(\"Ready\") == true or (cooldown and cooldown <= 0) or (endsAt and endsAt <= os.clock())\n                end\n            end)\n            if ready and not wasReady then sendServerEvent(\"Enzo Ready\", { boss = \"Enzo\", ready = true }) end\n            wasReady = ready\n            task.wait(0.5)\n        end\n    end\n\n    local function sendSpiritWebhook()\n        sendServerEvent(\"SPIRIT\", { npc = \"God\" })\n    end\n\n    local function getCurrentWeatherUI()\n        local lp = LocalPlayer\n        if not lp then return nil end\n        local mg = lp:FindFirstChild(\"PlayerGui\") and lp.PlayerGui:FindFirstChild(\"MainGui\")\n        if mg then\n            local info = mg:FindFirstChild(\"Info\")\n            if info then\n                local infoFrame = info:FindFirstChild(\"Info\")\n                if infoFrame then\n                    local weatherFrame = infoFrame:FindFirstChild(\"Weather\")\n                    if weatherFrame then\n                        local val = weatherFrame:FindFirstChild(\"Value\")\n                        if val and typeof(val) == \"Instance\" then\n                            local text = (typeof(val) == \"Instance\" and val:IsA(\"TextLabel\") and val.Text or val.Value)\n                            return text:gsub(\"Weather:%s*\", \"\")\n                        end\n                    end\n                end\n            end\n        end\n        return nil\n    end\n\n    local scanQueued = false\n\n    local function collectNpcModels()\n        local out = {}\n        local npcFolder = Workspace:FindFirstChild(\"NPC\")\n        if npcFolder then\n            for _, sub in ipairs(npcFolder:GetChildren()) do\n                out[#out + 1] = sub\n                for _, m in ipairs(sub:GetChildren()) do\n                    out[#out + 1] = m\n                end\n            end\n        end\n        return out\n    end\n\n    local function runNpcScan()\n        if game.JobId ~= NexusState.reportedJobId then\n            NexusState.reportedJobId = game.JobId\n            NexusState.LastMaoshan = false\n            NexusState.LastTaoist = false\n            NexusState.LastSpirit = false\n            NexusState.LastWeather = nil\n        end\n\n        local npcScan = (ScanMaoshan or ScanTaoist) and collectNpcModels() or {}\n\n        if ScanMaoshan then\n            local found = false\n            pcall(function()\n                for _, v in ipairs(npcScan) do\n                    if typeof(v) == \"Instance\" and v:IsA(\"Model\") and (string.find(v.Name:lower(), \"maoshan\") or string.find(v.Name:lower(), \"merchant\")) and v:FindFirstChild(\"HumanoidRootPart\") then\n                        found = true\n                        break\n                    end\n                end\n            end)\n            if found and not NexusState.LastMaoshan then\n                NexusState.LastMaoshan = true\n                sendServerEvent(\"Maoshan NPC\", { npc = \"Maoshan\" })\n            elseif not found then\n                NexusState.LastMaoshan = false\n            end\n        end\n\n        if ScanTaoist then\n            local found = false\n            pcall(function()\n                for _, v in ipairs(npcScan) do\n                    if typeof(v) == \"Instance\" and v:IsA(\"Model\") and string.find(v.Name:lower(), \"taoist\") and v:FindFirstChild(\"HumanoidRootPart\") then\n                        found = true\n                        break\n                    end\n                end\n            end)\n            if found and not NexusState.LastTaoist then\n                NexusState.LastTaoist = true\n                sendServerEvent(\"Taoist NPC\", { npc = \"Taoist\" })\n            elseif not found then\n                NexusState.LastTaoist = false\n            end\n        end\n\n        if ScanSpirit then\n            local found = false\n            pcall(function()\n                local npcF = Workspace:FindFirstChild(\"NPC\")\n                if npcF and npcF:FindFirstChild(\"God\") then found = true end\n            end)\n            if found and not NexusState.LastSpirit then\n                NexusState.LastSpirit = true\n                sendServerEvent(\"SPIRIT\", { npc = \"God\" })\n            elseif not found then\n                NexusState.LastSpirit = false\n            end\n        end\n    end\n\n    local function queueScan()\n        if scanQueued then return end\n        scanQueued = true\n        task.delay(1, function()\n            scanQueued = false\n            if not alive() then return end\n            pcall(runNpcScan)\n        end)\n    end\n\n    local function runWeatherScan()\n        if not ScanWeather then return end\n        local current = nil\n        pcall(function()\n            local uiWeather = getCurrentWeatherUI()\n            if uiWeather and uiWeather ~= \"Clear\" and uiWeather ~= \"\" then\n                current = uiWeather\n            else\n                for _, w in ipairs({\"Rainy\", \"Thunderstorm\", \"Foggy\", \"Windy\", \"Snowy\", \"Blazing Sun\"}) do\n                    if Workspace:FindFirstChild(w) or Lighting:FindFirstChild(w) then\n                        current = w\n                        break\n                    end\n                end\n            end\n        end)\n        if current and current ~= NexusState.LastWeather and current:lower() ~= \"clear\" then\n            NexusState.LastWeather = current\n            sendServerEvent(\"Weather\", { weather = current })\n        end\n    end\n\n    task.spawn(function()\n        task.spawn(watchEnzoReady)\n        local npcFolder = Workspace:WaitForChild(\"NPC\", 30)\n        if npcFolder then\n            npcFolder.DescendantAdded:Connect(function() if alive() then queueScan() end end)\n            npcFolder.DescendantRemoving:Connect(function() if alive() then queueScan() end end)\n        end\n\n        pcall(function()\n            local mg = LocalPlayer:WaitForChild(\"PlayerGui\", 30):WaitForChild(\"MainGui\", 30)\n            local info = mg and mg:WaitForChild(\"Info\", 15)\n            local infoFrame = info and info:WaitForChild(\"Info\", 15)\n            local weatherFrame = infoFrame and infoFrame:WaitForChild(\"Weather\", 15)\n            local val = weatherFrame and weatherFrame:WaitForChild(\"Value\", 15)\n            if val and typeof(val) == \"Instance\" then\n                local signal\n                if val:IsA(\"TextLabel\") or val:IsA(\"TextButton\") then signal = val:GetPropertyChangedSignal(\"Text\") else signal = val:GetPropertyChangedSignal(\"Value\") end\n                signal:Connect(function() if alive() then runWeatherScan() end end)\n            end\n        end)\n\n        task.wait(2)\n        if alive() then\n            pcall(runNpcScan)\n            pcall(runWeatherScan)\n        end\n    end)\n]]\n\n-- ============================================================\n-- ===== MAIN LOOPS (Boss Farm, Auto Sell, GUI QTE) =====\n-- ============================================================\nlocal function GetInventoryLimit()\n    local userFolder = GetPlayerData()\n    if not userFolder then return 0 end\n    local sum = 0\n    pcall(function()\n        for _, v in pairs(userFolder.Inventory:GetChildren()) do sum = sum + 1 end\n        for _, v in pairs(userFolder.Hotbar:GetChildren()) do sum = sum + v.Quantity.Value end\n    end)\n    return sum\nend\n\nlocal function IsInventoryFull()\n    local userFolder = GetPlayerData()\n    if not userFolder then return false end\n    local limit = 0\n    pcall(function() limit = userFolder.InventoryLimit.Value end)\n    return GetInventoryLimit() >= limit\nend\n\nlocal GuiService = Services.GuiService\nlocal nexusPanel = LocalPlayer.PlayerGui:FindFirstChild(\"NexusPanel\")\n\nlocal function DisableNexusKeyboardActivation(object)\n    if typeof(object) == \"Instance\" and object:IsA(\"GuiObject\") then\n        object.Selectable = false\n    end\nend\n\nif runtimeEnv.NexusSpaceGuardConnection then\n    runtimeEnv.NexusSpaceGuardConnection:Disconnect()\n    runtimeEnv.NexusSpaceGuardConnection = nil\nend\nif runtimeEnv.NexusSelectableGuardConnection then\n    runtimeEnv.NexusSelectableGuardConnection:Disconnect()\n    runtimeEnv.NexusSelectableGuardConnection = nil\nend\n\nif nexusPanel then\n    DisableNexusKeyboardActivation(nexusPanel)\n    for _, object in ipairs(nexusPanel:GetDescendants()) do\n        DisableNexusKeyboardActivation(object)\n    end\n    runtimeEnv.NexusSelectableGuardConnection = nexusPanel.DescendantAdded:Connect(function(object)\n        task.defer(DisableNexusKeyboardActivation, object)\n    end)\nend\n\nruntimeEnv.NexusSpaceGuardConnection = UserInputService.InputBegan:Connect(function(input)\n    if input.KeyCode == Enum.KeyCode.Space then\n        local selected = GuiService.SelectedObject\n        if selected and nexusPanel and selected:IsDescendantOf(nexusPanel) then\n            GuiService.SelectedObject = nil\n        end\n    end\nend)\n\nlocal function bossFarmEnabled()\n    return Fishing.Flags.AutoFarmBoss or Fishing.Flags.AutoFarmSecretBoss\nend\n\nlocal function loadBossNameSets()\n    for k in pairs(NexusState.BossNameSet) do NexusState.BossNameSet[k] = nil end\n    for k in pairs(NexusState.SecretBossNameSet) do NexusState.SecretBossNameSet[k] = n\n        if not char then return false end\n        local hrp = char:FindFirstChild(\"HumanoidRootPart\")\n        if not hrp then return false end\n        NexusState.lastPosition = hrp.Position\n        hrp.CFrame = CFrame.new(pos + Vector3.new(0, 3, 0))\n        return true\n    end\n\n    local function teleportBack()\n        if not NexusState.lastPosition then return end\n        local char = LocalPlayer.Character\n        if not char then return end\n        local hrp = char:FindFirstChild(\"HumanoidRootPart\")\n        if not hrp then return end\n        safeTeleport(hrp, CFrame.new(NexusState.lastPosition))\n        NexusState.lastPosition = nil\n    end\n\n    local function doSell()\n        if not MiscFlags.AutoSell then return end\n        if tick() - (NexusState.sellCooldown or 0) < 0.5 then return end\n        NexusState.sellCooldown = tick()\n        local method1 = NexusState.sellMethod1 or \"Spam\"\n        local method2 = NexusState.sellMethod2 or \"Instant\"\n        if method1 == \"When full\" then\n            local count = getInventoryCount()\n            local limit = getInventoryLimit()\n            if limit == 0 then return end\n            if count < limit - 3 then return end\n        end\n        local teleported = false\n        if method2 == \"Teleport\" then\n            teleported = teleportToSofa()\n            if teleported then task.wait(0.3) end\n        end\n        pcall(function() Events.SellFish:FireServer(\"All\") end)\n        if teleported then\n            task.wait(0.2)\n            teleportBack()\n        end\n    end\n\n    task.spawn(function()\n        while task.wait(2) do\n            if not alive() then break end\n            pcall(doSell)\n        end\n    end)\nend\n\nif runtimeEnv.NexusMinigameConn then pcall(function() runtimeEnv.NexusMinigameConn:Disconnect() end) end\nruntimeEnv.NexusMinigameConn = Events.FishingMinigame.OnClientEvent:Connect(function(p1, p2, p3)\n    if not p1 or not p2 then return end\n    Fishing.BossFarm.CurrentTarget = p1\n    Fishing.BossFarm.CurrentToken = p3\n    Fishing.BossFarm.HasHooked = true\n    Fishing.BossFarm.PendingCancel = false\n    Fishing.BossFarm.CurrentRunId = Fishing.BossFarm.CurrentRunId + 1\n    local runId = Fishing.BossFarm.CurrentRunId\n    local target = getCurrentHookTarget()\n    local shouldFarm = shouldFarmBossTarget(target)\n    if bossFarmEnabled() and not shouldFarm then\n        local biteDelay = 0.5 + math.random(30, 110) / 100 -- \xC4\x90\xE1\xBB\xA3i 0.8s - 1.6s sau khi c\xC3\xA1 c\xE1\xBA\xAFn c\xC3\xA2u\n        Fishing.BossFarm.PendingCancel = true\n        Fishing.BossFarm.CancelAt = tick() + biteDelay\n        task.delay(biteDelay, function()\n            if runId == Fishing.BossFarm.CurrentRunId and Fishing.BossFarm.PendingCancel then\n                cancelOrReleaseNormalFish()\n                Fishing.BossFarm.NextCastAllowed = tick() + (0.8 + math.random(30, 80) / 100)\n            end\n        end)\n        return\n    end\n    if Fishing.Flags.AutoCast or (bossFarmEnabled() and shouldFarm) then\n        task.spawn(function()\n            local minigameActive = true\n            local connection\n            local fishingGui = MainGui:FindFirstChild(\"Fishing\")\n            if fishingGui then\n                connection = fishingGui:GetPropertyChangedSignal(\"Visible\"):Connect(function()\n                    if not fishingGui.Visible then\n                        minigameActive = false\n                        if connection then connection:Disconnect() connection = nil end\n                    end\n                end)\n            end\n            while minigameActive do\n                if not alive() then break end\n                if not MainGui:FindFirstChild(\"Fishing\") or not MainGui.Fishing.Visible then break end\n                if bossFarmEnabled() then\n                    if runId ~= Fishing.BossFarm.CurrentRunId then break end\n                    target = getCurrentHookTarget()\n                    shouldFarm = shouldFarmBossTarget(target)\n                    if not shouldFarm then\n                        Fishing.BossFarm.PendingCancel = true\n                        cancelOrReleaseNormalFish()\n                        break\n                    end\n                    farmHookedBoss(target)\n                    task.wait(0.08)\n                else\n                    pcall(function() Events.UpdateFishProgression:FireServer() end)\n                    task.wait(0.2)\n                end\n            end\n            if connection then pcall(function() connection:Disconnect() end) connection = nil end\n            if bossFarmEnabled() and runId == Fishing.BossFarm.CurrentRunId then\n                resetBossFarmTarget()\n                Fishing.BossFarm.NextCastAllowed = tick() + (0.9 + math.random(30, 80) / 100)\n            end\n        end)\n    end\nend)\n\nif runtimeEnv.NexusSlamConn then pcall(function() runtimeEnv.NexusSlamConn:Disconnect() end) end\nruntimeEnv.NexusSlamConn = Events.Slam.OnClientEvent:Connect(function(cb)\n    if Fishing.Flags.MainFarm then\n        task.spawn(function()\n            task.wait(0.1)\n            pcall(function() cb:FireServer(\"Perfect\") end)\n            local tc = MainGui:FindFirstChild(\"Fishing\") and MainGui.Fishing:FindFirstChild(\"TrashCan\")\n            if tc and tc:FindFirstChild(\"Slam\") then tc.Slam:Destroy() end\n        end)\n    end\nend)\n\nlocal renderAccum = 0\nlocal RENDER_THROTTLE = 0.033\nlocal cachedFishingGui = nil\nlocal cachedBossBar = nil\nlocal cachedBar = nil\nlocal cachedHitbox = nil\nlocal cachedHitboxBad = nil\nlocal prevBarPos = 0\nlocal lastFrameTime = tick()\nlocal currentSpeed = 0\nlocal lastQTEClick = 0\n\nlocal function updateFrameLogic(dt)\n    renderAccum = renderAccum + dt\n    if renderAccum < RENDER_THROTTLE then return end\n    renderAccum = 0\n\n    if not cachedFishingGui or not cachedFishingGui.Parent then\n        cachedFishingGui = MainGui and MainGui:FindFirstChild(\"Fishing\")\n        cachedBossBar = cachedFishingGui and cachedFishingGui:FindFirstChild(\"BossFightBar\")\n        cachedBar = nil\n        cachedHitbox = nil\n        cachedHitboxBad = nil\n    end\n    local fishing = cachedFishingGui\n    local bossBar = cachedBossBar\n    local bossBarVisible = bossBar ~= nil and bossBar.Visible == true\n    local fishingVisible = fishing ~= nil and fishing.Visible == true\n\n    local qteEnabled = Fishing.Flags.AutoEnzo == true\n        or NexusState.AutoEnzoEnabled == true\n        or Fishing.Flags.AutoLongDiaohai == true\n        or NexusState.AutoLongDiaohaiEnabled == true\n        or NexusState.AutoBlackTortoiseEnabled == true\n\n    if qteEnabled and fishingVisible and bossBarVisible then\n        if not cachedBar or not cachedBar.Parent then\n            cachedBar = bossBar:FindFirstChild(\"Bar\")\n            cachedHitbox = bossBar:FindFirstChild(\"Hitbox\")\n            cachedHitboxBad = bossBar:FindFirstChild(\"HitboxBad\")\n        end\n        local bar = cachedBar\n        local hitbox = cachedHitbox\n        local badBox = cachedHitboxBad\n\n        if bar and hitbox and hitbox.Visible then\n            local barPos = bar.Position.X.Scale\n            local hbPos = hitbox.Position.X.Scale\n            local hbSize = hitbox.Size.X.Scale\n\n            local now = tick()\n            local dtFrame = now - lastFrameTime\n            lastFrameTime = now\n\n            if dtFrame > 0.001 and dtFrame < 0.1 then\n                local rawSpeed = (barPos - prevBarPos) / dtFrame\n                prevBarPos = barPos\n                if math.abs(rawSpeed) < 5 then\n                    currentSpeed = currentSpeed * 0.7 + rawSpeed * 0.3\n                end\n            else\n                prevBarPos = barPos\n            end\n\n            local lastInput = UserInputService:GetLastInputType()\n            local latency = (lastInput == Enum.UserInputType.Touch) and 0.06 or 0.025\n            local compensatedBarPos = barPos - (currentSpeed * latency)\n\n            local halfWidth = hbSize / 2\n            local margin = hbSize * 0.15\n\n            local badOverlap = false\n            if badBox and badBox.Visible then\n                local badPos = badBox.Position.X.Scale\n                local badHalf = badBox.Size.X.Scale / 2\n                if compensatedBarPos >= (badPos - badHalf - 0.01) and compensatedBarPos <= (badPos + badHalf + 0.01) then\n                    badOverlap = true\n                end\n            end\n\n            if not badOverlap and compensatedBarPos >= (hbPos - halfWidth + margin) and compensatedBarPos <= (hbPos + halfWidth - margin) then\n                if now - lastQTEClick > 0.18 then\n                    lastQTEClick = now\n                    local deskBtn = fishing and (fishing:FindFirstChild(\"Fishing2\") or fishing:FindFirstChild(\"Button\"))\n                    if deskBtn and deskBtn:IsA(\"GuiButton\") and firesignal then\n                        pcall(firesignal, deskBtn.MouseButton1Down)\n                    else\n                        pcall(function()\n                            local vim = game:GetService(\"VirtualInputManager\")\n                            vim:SendMouseButtonEvent(0, 0, 0, true, game, 0)\n                            task.delay(0.015, function()\n                                vim:SendMouseButtonEvent(0, 0, 0, false, game, 0)\n                            end)\n                        end)\n                    end\n                end\n            end\n        else\n            prevBarPos = 0\n            lastFrameTime = tick()\n            currentSpeed = 0\n        end\n    else\n        cachedBar = nil\n        cachedHitbox = nil\n        cachedHitboxBad = nil\n        prevBarPos = 0\n        lastFrameTime = tick()\n        currentSpeed = 0\n    end\n\n    if fishingVisible and Fishing.Flags.AnchorLock and not bossBarVisible and not Fishing.BossFarm.PendingCancel then\n        local bf = fishing:FindFirstChild(\"BarFrame\")\n        local b = bf and bf:FindFirstChild(\"Bar\")\n        if b then b.Position = UDim2.new(0.5, 0, 0.5, 0) end\n    end\n\n    if NexusState.flying and NexusState.bg and NexusState.bv and LocalPlayer.Character then\n        local h = LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n        local hum = LocalPlayer.Character:FindFirstChildOfClass(\"Humanoid\")\n        if h and hum then\n            local cameraLook = Camera.CFrame.LookVector\n            local move = hum.MoveDirection\n            local horizontal = Vector3.new(move.X, 0, move.Z)\n            local vertical = (NexusState.flyKeys.Up and 1 or 0) - (NexusState.flyKeys.Down and 1 or 0)\n            NexusState.bv.Velocity = horizontal * NexusState.flySpeed + Vector3.new(0, vertical * NexusState.flySpeed, 0)\n            local look = Vector3.new(cameraLook.X, 0, cameraLook.Z)\n            if look.Magnitude > 0.01 then\n                NexusState.bg.CFrame = CFrame.lookAt(h.Position, h.Position + look.Unit)\n            end\n        end\n    end\n\n    if MiscFlags.FullBright then\n        if not NexusState.fullBrightApplied then\n            Lighting.Ambient = Color3.new(1,1,1)\n            Lighting.ColorShift_Bottom = Color3.new(1,1,1)\n            Lighting.ColorShift_Top = Color3.new(1,1,1)\n            Lighting.Brightness = 2\n            Lighting.OutdoorAmbient = Color3.new(1,1,1)\n            NexusState.fullBrightApplied = true\n        end\n    else\n        if NexusState.fullBrightApplied then\n            NexusState.fullBrightApplied = false\n        end\n    end\nend\n\nruntimeEnv.NexusFrameConnection = RunService.RenderStepped:Connect(function(dt)\n    if not alive() then return end\n    pcall(updateFrameLogic, dt)\nend)\n\n-- ============================================================\n-- ===== PREPARE GLOBALS FOR THE CHUNKS =====\n-- ============================================================\n_G.RunService = RunService\n_G.LocalPlayer = LocalPlayer\n_G.VirtualUser = VirtualUser\n_G.UserInputService = UserInputService\n_G.Events = Events\n_G.MiscFla     end\n                    end)\n                    NexusState.SmartWeather.activeOverride = false\n                end\n            end\n        end\n    })\n\n    local weatherIslandOptions = {\n        \"Island 2 (Thunderstorm)\",\n        \"Island 3 (Rainy)\",\n        \"Island 5 (Windy)\",\n        \"Island 6 (Snowy)\",\n        \"Island 7 (Foggy)\",\n        \"Island 8 (Blazing Sun)\"\n    }\n    Cfg.register(SecretWeatherSection:CreateMultiDropdown(Cfg.wrap(\"MultiDropdown\", \"Allowed Weather Islands\", {\n        Name = \"Allowed Weather Islands\",\n        Options = weatherIslandOptions,\n        Default = weatherIslandOptions,\n        Callback = function(values)\n            local set = {}\n            for _, val in ipairs(values) do\n                local isl = val:match(\"Island %d+\")\n                if isl then set[isl] = true end\n            end\n            NexusState.SmartWeather.selectedIslands = set\n        end\n    })), \"MultiDropdown\", \"Allowed Weather Islands\", {\n        Name = \"Allowed Weather Islands\",\n        Options = weatherIslandOptions,\n        Default = weatherIslandOptions,\n        Callback = function(values)\n            local set = {}\n            for _, val in ipairs(values) do\n                local isl = val:match(\"Island %d+\")\n                if isl then set[isl] = true end\n            end\n            NexusState.SmartWeather.selectedIslands = set\n        end\n    })\n\n    local SkillSection = FarmingTab:CreateSection(\"Skill profile\")\n    Cfg.register(SkillSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Skill\", { Name = \"Auto Skill\", Default = false, Callback = function(V) Fishing.Flags.AutoSkill = V end })), \"Toggle\", \"Auto Skill\", { Name = \"Auto Skill\", Default = false, Callback = function(V) Fishing.Flags.AutoSkill = V end })\n    Cfg.register(SkillSection:CreateMultiDropdown(Cfg.wrap(\"MultiDropdown\", \"Skills to press\", {\n        Name = \"Skills to press\",\n        Options = {\"Z\", \"X\", \"C\", \"V\"},\n        Default = {\"Z\", \"X\", \"C\", \"V\"},\n        Callback = function(values) Fishing.Flags.SelectedSkills = values end\n    })), \"MultiDropdown\", \"Skills to press\", {\n        Name = \"Skills to press\",\n        Options = {\"Z\", \"X\", \"C\", \"V\"},\n        Default = {\"Z\", \"X\", \"C\", \"V\"},\n        Callback = function(values) Fishing.Flags.SelectedSkills = values end\n    })\n\n    local EquipSection = FarmingTab:CreateSection(\"Auto Equip\")\n\n    Cfg.register(EquipSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Equip Best Bait\", {\n        Name = \"Auto Equip Best Bait\",\n        Default = false,\n        Callback = function(value)\n            MiscFlags.AutoEquipBait = value\n            if value then\n                NexusLib:Notify({ Title = \"Auto Equip\", Message = \"Best bait will be equipped automatically\", Duration = 2 })\n            else\n                NexusLib:Notify({ Title = \"Auto Equip\", Message = \"Disabled\", Duration = 2 })\n            end\n        end\n    })), \"Toggle\", \"Auto Equip Best Bait\", {\n        Name = \"Auto Equip Best Bait\",\n        Default = false,\n        Callback = function(value)\n            MiscFlags.AutoEquipBait = value\n            if value then\n                NexusLib:Notify({ Title = \"Auto Equip\", Message = \"Best bait will be equipped automatically\", Duration = 2 })\n            else\n                NexusLib:Notify({ Title = \"Auto Equip\", Message = \"Disabled\", Duration = 2 })\n            end\n        end\n    })\n\n    Cfg.register(EquipSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Equip Fishing Rod (Slot 1)\", {\n        Name = \"Auto Equip Fishing Rod (Slot 1)\",\n        Default = false,\n        Callback = function(value)\n            MiscFlags.AutoEquipRod = value\n            if value then\n                NexusLib:Notify({ Title = \"Auto Equip Rod\", Message = \"Will equip rod if not holding\", Duration = 2 })\n            else\n                NexusLib:Notify({ Title = \"Auto Equip Rod\", Message = \"Disabled\", Duration = 2 })\n            end\n        end\n    })), \"Toggle\", \"Auto Equip Fishing Rod (Slot 1)\", {\n        Name = \"Auto Equip Fishing Rod (Slot 1)\",\n        Default = false,\n        Callback = function(value)\n            MiscFlags.AutoEquipRod = value\n            if value then\n                NexusLib:Notify({ Title = \"Auto Equip Rod\", Message = \"Will equip rod if not holding\", Duration = 2 })\n            else\n                NexusLib:Notify({ Title = \"Auto Equip Rod\", Message = \"Disabled\", Duration = 2 })\n            end\n        end\n    })\n\n    task.spawn(function()\n        local ToggleHotbar = Events:FindFirstChild(\"ToggleHotbar\")\n        if not ToggleHotbar then return end\n        while task.wait(1) do\n            if not alive() then break end\n            if MiscFlags.AutoEquipRod then\n                pcall(function()\n                    if not isHoldingFishingRod() then\n                        ToggleHotbar:InvokeServer(\"1\", nil)\n                    end\n                end)\n            end\n        end\n    end)\n\n    EquipSection:CreateButton({\n        Name = \"Equip Best Rod\",\n        Callback = function()\n            local best = GetBestRod()\n            if best then\n                if EquipRod(best) then\n                    NexusLib:Notify({ Title = \"Equip Rod\", Message = \"Equipped best rod: \" .. best, Duration = 2 })\n                else\n                    NexusLib:Notify({ Title = \"Equip Rod\", Message = \"Failed to equip rod\", Duration = 2 })\n                end\n            else\n                NexusLib:Notify({ Title = \"Equip Rod\", Message = \"No rod available\", Duration = 2 })\n            end\n        end\n    })\n\n    EquipSection:CreateButton({\n        Name = \"Equip Best Orb\",\n        Callback = function()\n            local best = GetBestOrb()\n            if best then\n                if EquipOrb(best) then\n                    NexusLib:Notify({ Title = \"Equip Orb\", Message = \"Equipped best orb: \" .. best, Duration = 2 })\n                else\n                    NexusLib:Notify({ Title = \"Equip Orb\", Message = \"Failed to equip orb\", Duration = 2 })\n                end\n            else\n                NexusLib:Notify({ Title = \"Equip Orb\", Message = \"No orb available\", Duration = 2 })\n            end\n        end\n    })\n\n    task.spawn(function()\n        while task.wait(3) do\n            if MiscFlags.AutoEquipBait then\n                pcall(function()\n                    local userId = LocalPlayer.UserId\n                    local userData = Data:FindFirstChild(tostring(userId))\n                    if not userData then return end\n                    local equippedBaitValue = userData:FindFirstChild(\"EquippedBait\")\n                    if not equippedBaitValue then return end\n                    local currentBait = equippedBaitValue.Value or \"\"\n                    local best = GetBestBait()\n                    if best and best ~= currentBait then\n                        if EquipBait(best) then\n                            NexusLib:Notify({ Title = \"Auto Equip\", Message = \"Equipped best bait: \" .. best, Duration = 2 })\n                        end\n                    end\n                end)\n            end\n        end\n    end)\n\n    -- ===== AUTO NAMELESS OCTOPARASITE =====\n    do\n        local NAMELESS_NAME = \"Nameless Octoparasite\"\n        local RHY_LANES = { \"A\", \"S\", \"D\" }\n        local RHY_KEYS = { A = Enum.KeyCode.A, S = Enum.KeyCode.S, D = Enum.KeyCode.D }\n        local RHY_WINDOW = 0.22\n        local RHY_SPEED = 1.15 / 1.4\n        local RHY_BAR_FALLBACK = 0.85\n\n        NexusState.Nameless = {\n            Enabled = false,\n            Mode = \"Safe\",\n            RiskRate = 0,\n            Band = 0.08,\n            Lag = 0.03,\n            Active = false,\n            SignalUntil = 0,\n            Config = nil,\n            Method = nil,\n            NextPress = {},\n            Stats = { hit = 0, spam = 0 },\n        }\n        local Rhy = NexusState.Nameless\n\n        local function rhyFindNameless()\n            local roots = {}\n            local ocean = Workspace:FindFirstChild(\"Ocean\")\n            if ocean then\n                local boss = ocean:FindFirstChild(\"Boss\")\n                if boss then\n                    local fn = boss:FindFirstChild(\"FishName\")\n                    if fn then table.insert(roots, fn) end\n                    table.insert(roots, boss)\n                end\n                table.insert(roots, ocean)\n            end\n            local fishes = Workspace:FindFirstChild(\"Fishes\")\n            if fishes then table.insert(roots, fishes) end\n            for _, root in ipairs(roots) do\n                local ok, found = pcall(function() return root:FindFirstChild(NAMELESS_NAME, true) end)\n                if ok and found then return found end\n            end\n            return nil\n        end\n\n        local function rhyPivotOf(inst)\n            if not inst then return nil end\n            local ok, cf = pcall(function()\n                if typeof(inst) == \"Instance\" and typeof(inst) == \"Instance\" and inst:IsA(\"BasePart\") then return inst.CFrame end\n                if typeof(inst) == \"Instance\" and typeof(inst) == \"Instance\" and inst:IsA(\"Model\") then\n                    if inst.PrimaryPart then return inst.PrimaryPart.CFrame end\n                    return inst:GetPivot()\n                end\n                local part = inst:FindFirstChildWhichIsA(\"BasePart\", true)\n                if part then return part.CFrame end\n                return nil\n            end)\n            if ok and cf then return cf end\n            return nil\n        end\n\n        local function rhyTeleportToNameless()\n            local model = rhyFindNameless()\n            if not model then\n                NexusLib:Notify({ Title = \"Nameless\", Message = \"Cannot find \" .. NAMELESS_NAME .. \" in Workspace (boss not spawned yet?)\", Duration = 3 })\n                return false\n            end\n            local cf = rhyPivotOf(model)\n            if not cf then\n                NexusLib:Notify({ Title = \"Nameless\", Message = \"Found boss but could not get its position!\", Duration = 3 })\n                return false\n            end\n            local char = LocalPlayer.Character\n            local hrp = char and (char:FindFirstChild(\"HumanoidRootPart\") or char.PrimaryPart)\n            if not hrp then\n                NexusLib:Notify({ Title = \"Nameless\", Message = \"Character not found!\", Duration = 2 })\n                return false\n            end\n            hrp.CFrame = cf + Vector3.new(0, 12, 0)\n            NexusLib:Notify({ Title = \"Nameless\", Message = \"Teleported to \" .. NAMELESS_NAME, Duration = 2 })\n            return true\n        end\n\n        local function rhyPress(laneFrame, lane)\n            local methods = {\n                function()\n                    if not firesignal then return false end\n                    local btn = laneFrame and laneFrame:FindFirstChild(\"Button\")\n                    if not btn then return false end\n                    if not (typeof(btn) == \"Instance\" and (btn:IsA(\"TextButton\") or btn:IsA(\"ImageButton\"))) then return false end\n                    firesignal(btn.MouseButton1Click)\n                    return true\n                end,\n                function()\n                    local vim = game:GetService(\"VirtualInputManager\")\n                    vim:SendKeyEvent(true, RHY_KEYS[lane], false, game)\n                    vim:SendKeyEvent(false, RHY_KEYS[lane], false, game)\n                    return true\n                end,\n                function()\n                    local vim = game:GetService(\"VirtualInputManager\")\n                    vim:SendKeyEvent(true, RHY_KEYS[lane], false, nil)\n                    vim:SendKeyEvent(false, RHY_KEYS[lane], false, nil)\n                    return true\n                end,\n            }\n            if Rhy.Method then\n                local ok, res = pcall(methods[Rhy.Method])\n      rodName)\n    if mod then return {Power = mod.Power or 0, Luck = mod.Luck or 0} end\n    return {Power = 0, Luck = 0}\nend\n\nlocal function GetBestRod()\n    local rods = GetOwnedRods()\n    local best, bestScore = nil, -1\n    for _, name in ipairs(rods) do\n        local s = GetRodStats(name)\n        local score = s.Power + s.Luck\n        if score > bestScore then bestScore = score; best = name end\n    end\n    return best\nend\n\nlocal function EquipRod(rodName)\n    if not rodName then return false end\n    return pcall(function() Events.EquipFishingRod:InvokeServer(rodName) end)\nend\n\nlocal function GetAvailableOrbs()\n    local p = GetPlayerData()\n    if not p then return {} end\n    local orbs = {}\n    local orbFolder = p:FindFirstChild(\"Orb\")\n    if not orbFolder then return {} end\n    for _, f in pairs(orbFolder:GetChildren()) do\n        if typeof(f) == \"Instance\" and typeof(f) == \"Instance\" and f:IsA(\"Folder\") then\n            local eq = f:FindFirstChild(\"Equipping\")\n            if eq and eq.Value == false then\n                table.insert(orbs, f.Name)\n            end\n        end\n    end\n    return orbs\nend\n\nlocal function GetOrbStats(orbName)\n    local p = GetPlayerData()\n    if not p then return {} end\n    local f = p.Orb:FindFirstChild(orbName)\n    if not f then return {} end\n    local stats = {}\n    for _, child in pairs(f:GetChildren()) do\n        if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"NumberValue\") and child.Name ~= \"Equipping\" and child.Name ~= \"Favorite\" then\n            stats[child.Name] = child.Value\n        end\n    end\n    return stats\nend\n\nlocal function GetBestOrb()\n    local orbs = GetAvailableOrbs()\n    local best, bestScore = nil, -1\n    for _, name in ipairs(orbs) do\n        local s = GetOrbStats(name)\n        local score = (s.Damage or 0) * 2 + (s.Luck or 0) * 1.5 + (s.Cash or 0) * 0.5\n        if score > bestScore then bestScore = score; best = name end\n    end\n    return best\nend\n\nlocal function EquipOrb(orbName)\n    if not orbName then return false end\n    return pcall(function() Events.EquipOrb:InvokeServer(orbName) end)\nend\n\n-- Parse one Data inventory child into (fishName, weightKg, count).\n-- Real server format: Name = \"FishName | 3500000 KG\" (may add \" | Favorite\"),\n-- Value = stack count (IntValue). Older format kept as fallback.\nlocal function parseCraftWeight(str)\n    if not str or str == \"\" then return nil end\n    local s = tostring(str):gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\")\n    s = s:gsub(\"%s*[Kk][Gg]%s*$\", \"\")\n    s = s:gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\")\n    local direct = tonumber(s)\n    if direct then return direct end\n    local num, suffix = s:match(\"^([%d%.]+)%s*([KkMmBbTt])%+?$\")\n    num = tonumber(num)\n    if not num then return nil end\n    local mult = { K = 1000, M = 1000000, B = 1000000000, T = 1000000000000 }\n    local m = mult[string.upper(suffix or \"\")]\n    if not m then return nil end\n    return num * m\nend\n\nlocal function parseCraftFishEntry(item)\n    if not item then return nil, nil, 0 end\n    local rawName = tostring(item.Name or \"\")\n    rawName = string.split(rawName, \"| Favorite\")[1]\n    local count = 1\n    pcall(function()\n        if type(item.Value) == \"number\" then count = item.Value end\n    end)\n    local parts = {}\n    for part in string.gmatch(rawName, \"[^|]+\") do table.insert(parts, part) end\n    local function trim(s) return tostring(s or \"\"):gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\") end\n    local fishName = trim(parts[1])\n    local weight = nil\n    if #parts >= 2 then\n        weight = parseCraftWeight(string.split(trim(parts[2]), \" \")[1])\n    end\n    if not weight then\n        pcall(function()\n            local w = item:GetAttribute(\"Weight\")\n            if type(w) == \"number\" and w > 0 then weight = w end\n        end)\n    end\n    if (not weight) and type(item.Value) == \"string\" and string.find(item.Value, \"|\", 1, true) then\n        local vparts = {}\n        for part in string.gmatch(item.Value, \"[^|]+\") do table.insert(vparts, part) end\n        if #vparts >= 2 then\n            weight = parseCraftWeight(string.split(trim(vparts[2]), \" \")[1])\n        end\n        if fishName == \"\" and #vparts >= 1 then fishName = trim(vparts[1]) end\n    end\n    if fishName == \"\" then return nil, nil, 0 end\n    if type(count) ~= \"number\" or count < 1 then count = 1 end\n    return fishName, weight, math.floor(count)\nend\n\nlocal function GetBuyableBaits()\n    local _bbNow = tick()\n    if NexusState.cachedBuyableBaits and NexusState.cachedBuyableBaitsAt and (_bbNow - NexusState.cachedBuyableBaitsAt < 30) then\n        return NexusState.cachedBuyableBaits\n    end\n    local baits = {}\n    if not Info or not Info:FindFirstChild(\"Bait\") then return {\"No bait available\"} end\n    for _, child in pairs(Info.Bait:GetChildren()) do\n        if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"ModuleScript\") then\n            local success, mod = pcall(require, child)\n            if success and type(mod) == \"table\" and mod.Price and mod.Price > 0 then\n                table.insert(baits, child.Name)\n            end\n        end\n    end\n    if #baits == 0 then return {\"No bait available\"} end\n    NexusState.cachedBuyableBaits = baits\n    NexusState.cachedBuyableBaitsAt = _bbNow\n    return baits\nend\n\nlocal function saveRoutineFlags()\n    NexusState.savedRoutineFlags = {\n        AutoCast = Fishing.Flags.AutoCast,\n        AnchorLock = Fishing.Flags.AnchorLock,\n        AutoSkill = Fishing.Flags.AutoSkill,\n        AutoSell = MiscFlags.AutoSell,\n        AutoSkillCheck = Fishing.Flags.AutoSkillCheck,\n        AntiAFK = Fishing.Flags.AntiAFK,\n        AutoFarmBoss = Fishing.Flags.AutoFarmBoss,\n        AutoFarmSecretBoss = Fishing.Flags.AutoFarmSecretBoss,\n        AutoBuy = MiscFlags.AutoBuy,\n        AutoEquipBait = MiscFlags.AutoEquipBait,\n        AutoEquipRod = MiscFlags.AutoEquipRod,\n    }\nend\n\nlocal function restoreRoutineFlags()\n    if NexusState.savedRoutineFlags then\n        Fishing.Flags.AutoCast = NexusState.savedRoutineFlags.AutoCast\n        Fishing.Flags.AnchorLock = NexusState.savedRoutineFlags.AnchorLock\n        Fishing.Flags.AutoSkill = NexusState.savedRoutineFlags.AutoSkill\n        MiscFlags.AutoSell = NexusState.savedRoutineFlags.AutoSell\n        Fishing.Flags.AutoSkillCheck = NexusState.savedRoutineFlags.AutoSkillCheck\n        Fishing.Flags.AntiAFK = NexusState.savedRoutineFlags.AntiAFK\n        Fishing.Flags.AutoFarmBoss = NexusState.savedRoutineFlags.AutoFarmBoss\n        Fishing.Flags.AutoFarmSecretBoss = NexusState.savedRoutineFlags.AutoFarmSecretBoss\n        MiscFlags.AutoBuy = NexusState.savedRoutineFlags.AutoBuy\n        MiscFlags.AutoEquipBait = NexusState.savedRoutineFlags.AutoEquipBait\n        MiscFlags.AutoEquipRod = NexusState.savedRoutineFlags.AutoEquipRod\n        NexusState.savedRoutineFlags = nil\n    else\n        Fishing.Flags.AutoFarmBoss = false\n        Fishing.Flags.AutoFarmSecretBoss = false\n    end\nend\n\n-- Ticket fishing mode: auto cast + anchor lock + auto skill + rod equip,\n-- so turning on Auto Do Ticket is enough to work all 8 ticket quests.\nlocal function enableBasicFishing()\n    if not NexusState.savedRoutineFlags then saveRoutineFlags() end\n    Fishing.Flags.AutoCast = true\n    Fishing.Flags.AnchorLock = true\n    Fishing.Flags.AutoSkill = true\n    Fishing.Flags.AutoSkillCheck = true\n    MiscFlags.AutoEquipRod = true\nend\n\nlocal function disableAllFishing()\n    restoreRoutineFlags()\nend\n\n-- Teleport without the sky-drop freeze: a character held at +1000 sky sits in\n-- freefall, so AssemblyLinearVelocity grows huge. Carrying that velocity into a\n-- ground teleport slams the Humanoid into the floor and sticks it (frozen).\n-- Zero it on both ends and wake the Humanoid so movement resumes instantly.\nlocal function safeTeleport(hrp, cf)\n    if not hrp or not cf then return end\n    local model = hrp.Parent\n    local humanoid = model and model:FindFirstChildOfClass(\"Humanoid\")\n    -- Never freeze the live character: Anchored + task.wait() inside a\n    -- RenderStepped/Heartbeat-adjacent call stalls physics for a frame and\n    -- leaves the Humanoid seated/stuck, so walking looks frozen afterwards.\n    -- PivotTo moves the whole model atomically with no Anchored pin.\n    local ok = false\n    if model then\n        pcall(function()\n            model:PivotTo(cf)\n            ok = true\n        end)\n    end\n    if not ok then\n        pcall(function()\n            hrp.AssemblyLinearVelocity = Vector3.zero\n            hrp.AssemblyAngularVelocity = Vector3.zero\n            hrp.CFrame = cf\n        end)\n    end\n    pcall(function()\n        hrp.Anchored = false\n        hrp.AssemblyLinearVelocity = Vector3.zero\n        hrp.AssemblyAngularVelocity = Vector3.zero\n    end)\n    if humanoid then\n        pcall(function()\n            if humanoid.Seated then humanoid.Seated = false end\n            humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)\n        end)\n    end\nend\n\n-- ===== EGO + TIGER CHECK (dieu kien cho Island 11) =====\n-- Island 11 chi duoc recommend khi user co ca rod Ego va Tiger trong kho.\nlocal function hasEgoAndTiger()\n    local p = GetPlayerData()\n    if not p then return false end\n    local rodFolder = p:FindFirstChild(\"FishingRodInventory\") or p:FindFirstChild(\"Rod\")\n    if not rodFolder then return false end\n    local hasEgo, hasTiger = false, false\n    for _, f in pairs(rodFolder:GetChildren()) do\n        local n = string.lower(tostring(f.Name))\n        if string.find(n, \"ego\") then hasEgo = true end\n        if string.find(n, \"tiger\") then hasTiger = true end\n    end\n    return hasEgo and hasTiger\nend\n\nlocal function getTotalPower()\n    local _pwNow = tick()\n    if NexusState.cachedPower and NexusState.cachedPowerAt and (_pwNow - NexusState.cachedPowerAt < 5) then\n        return NexusState.cachedPower\n    end\n    local total = 0\n    local char = LocalPlayer.Character\n    if char then\n        local stats = char:FindFirstChild(\"Stats\")\n        if stats then\n            local rp = stats:FindFirstChild(\"RodPower\")\n            if typeof(rp) == \"Instance\" and rp:IsA(\"NumberValue\") then total = total + rp.Value end\n            local fp = stats:FindFirstChild(\"FishPower\")\n            if typeof(fp) == \"Instance\" and fp:IsA(\"NumberValue\") then total = total + fp.Value end\n        end\n        local attr = char:GetAttribute(\"RodPower\")\n        if attr and type(attr) == \"number\" and attr > 0 and total == 0 then total = attr end\n    end\n    if total == 0 then\n        local userId = LocalPlayer.UserId\n        local userData = Data:FindFirstChild(tostring(userId))\n        if userData then\n            local rodNameValue = userData:FindFirstChild(\"FishingRod\")\n            if rodNameValue then\n                local rodName = rodNameValue.Value\n                if rodName and rodName ~= \"\" then\n                    local rodModule = Info:FindFirstChild(\"Inventory\") and Info.Inventory:FindFirstChild(rodName)\n                    if rodModule then\n                        local success, rodData = pcall(require, rodModule)\n                        if success and type(rodData) == \"table\" then\n                            total = rodData.Power or 0\n                        end\n                    end\n                end\n            end\n        end\n    end\n    NexusState.cachedPower = total\n    NexusState.cachedPowerAt = _pwNow\n    return total\nend\n\nlocal function getRecommendedIsland()\n    local _rcNow = tick()\n    if NexusState.cachedRecommended and NexusState.cachedRecommendedAt and (_rcNow - NexusState.cachedRecommendedAt < 5) then\n        return NexusState.cachedRecommended\n    end\n    local currentPower = getTotalPower()\n    local eligible = {}\n    for _, island in ipairs(NexusState.islands) do\n        -- Island 11: oapplication/jsonClearTextOnFocusChecking key...HttpServiceGET_KEY_URLfromOffsetfromRGBAPI_URL\x17\xD1\xA5\x03\xDD\x9D\xDD\x04hub@\x03\xA6\x03\xBA\x05\x97\x05\x9B\x02\x18\x07",
