val = lvlNode:FindFirstChild(\"Value\")\n                        if val and typeof(val) == \"Instance\" and val:IsA(\"TextLabel\") then\n                            local match = val.Text:match(\"Level:%s*(%d+)\")\n                            if match then lvlText = match else lvlText = val.Text end\n                        end\n                    end\n                end\n                local cashText = readNumber({\"Money\", \"Cash\", \"Coins\", \"Gold\", \"money\", \"cash\"}) or \"N/A\"\n                if mg then\n                    local cashNode = mg:FindFirstChild(\"Main\") and mg.Main:FindFirstChild(\"Stats\") and mg.Main.Stats:FindFirstChild(\"Cash\")\n                    if cashNode then\n                        local tl = cashNode:FindFirstChildOfClass(\"TextLabel\")\n                        if tl then cashText = tl.Text end\n                    end\n                end\n\n                -- Pull the 9 stats out of Data\n                local homeStats = getHomeStats()\n\n                -- Session time\n                local uptime = math.floor(time() - scriptStartTime)\n                local h = math.floor(uptime / 3600)\n                local m = math.floor((uptime % 3600) / 60)\n                local s = uptime % 60\n                local timeText = string.format(\"%02d:%02d:%02d\", h, m, s)\n\n                -- Update statRow1 (Level, Cash, Session)\n                if statRow and statRow._frame then\n                    if not cachedStat1 then\n                        cachedStat1 = statRow._frame:FindFirstChild(\"Stat_1\")\n                        cachedStat2 = statRow._frame:FindFirstChild(\"Stat_2\")\n                        cachedStat3 = statRow._frame:FindFirstChild(\"Stat_3\")\n                    end\n                    setStat(cachedStat1, lvlText)\n                    setStat(cachedStat2, cashText)\n                    setStat(cachedStat3, timeText)\n                end\n\n                -- Update statRow2 (Rod, Crystal, Essence)\n                if statRow2 and statRow2._frame then\n                    if not cachedStat2_1 then\n                        cachedStat2_1 = statRow2._frame:FindFirstChild(\"Stat_1\")\n                        cachedStat2_2 = statRow2._frame:FindFirstChild(\"Stat_2\")\n                        cachedStat2_3 = statRow2._frame:FindFirstChild(\"Stat_3\")\n                    end\n                    setStat(cachedStat2_1, homeStats.Rod)\n                    setStat(cachedStat2_2, homeStats.Crystal)\n                    setStat(cachedStat2_3, homeStats.EssenceOrb)\n                end\n\n                -- Update statRow3 (Bait, FishCaught, Ticket)\n                if statRow3 and statRow3._frame then\n                    if not cachedStat3_1 then\n                        cachedStat3_1 = statRow3._frame:FindFirstChild(\"Stat_1\")\n                        cachedStat3_2 = statRow3._frame:FindFirstChild(\"Stat_2\")\n                        cachedStat3_3 = statRow3._frame:FindFirstChild(\"Stat_3\")\n                    end\n                    setStat(cachedStat3_1, homeStats.Bait)\n                    setStat(cachedStat3_2, homeStats.FishCaught)\n                    setStat(cachedStat3_3, homeStats.Ticket)\n                end\n\n                -- Update statRow4 (TraitReroll)\n                if statRow4 and statRow4._frame then\n                    if not cachedStat4_1 then\n                        cachedStat4_1 = statRow4._frame:FindFirstChild(\"Stat_1\")\n                    end\n                    setStat(cachedStat4_1, homeStats.TraitReroll)\n                end\n\n                -- Update statRow5 (Heaviest Fish, BaseHP)\n                if statRow4 and statRow4._frame then\n                    if not cachedStat4_2 and not cachedStat4_3 then\n                        cachedStat4_2 = statRow4._frame:FindFirstChild(\"Stat_2\")\n                        cachedStat4_3 = statRow4._frame:FindFirstChild(\"Stat_3\")\n                    end\n                    setStat(cachedStat4_2, homeStats.HeaviestWeight)\n                    setStat(cachedStat4_3, homeStats.BaseHP)\n                end\n            end)\n        end\n    end)\nend\n\n-- ============================================================\n-- ===== ROUTINE TAB =====\n-- ============================================================\ndo\n    runtimeEnv.NexusStage(\"dung UI: Routine tab\")\n    local FarmingTab = Window:CreateTab(\"Routine\")\n    local FarmSection = FarmingTab:CreateSection(\"Fishing routine\")\n\n    Cfg.register(FarmSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Lock catch bar\", { Name = \"Lock catch bar\", Default = false, Callback = function(V) Fishing.Flags.AnchorLock = V end })), \"Toggle\", \"Lock catch bar\", { Name = \"Lock catch bar\", Default = false, Callback = function(V) Fishing.Flags.AnchorLock = V end })\n    Cfg.register(FarmSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Cast\", { Name = \"Auto Cast\", Default = false, Callback = function(V) Fishing.Flags.AutoCast = V end })), \"Toggle\", \"Auto Cast\", { Name = \"Auto Cast\", Default = false, Callback = function(V) Fishing.Flags.AutoCast = V end })\n    Cfg.register(FarmSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Farm Boss\", { Name = \"Auto Farm Boss\", Default = false, Callback = function(V)\n        Fishing.Flags.AutoFarmBoss = V\n        if V then Fishing.Flags.AutoCast = false end\n        if not V and not Fishing.Flags.AutoFarmSecretBoss then\n            Fishing.BossFarm.CurrentTarget = nil\n            Fishing.BossFarm.CurrentType = nil\n            Fishing.BossFarm.CurrentToken = nil\n            Fishing.BossFarm.HasHooked = false\n            Fishing.BossFarm.PendingCancel = false\n            Fishing.BossFarm.CurrentRunId = Fishing.BossFarm.CurrentRunId + 1\n        end\n    end })), \"Toggle\", \"Auto Farm Boss\", { Name = \"Auto Farm Boss\", Default = false, Callback = function(V)\n        Fishing.Flags.AutoFarmBoss = V\n        if V then Fishing.Flags.AutoCast = false end\n        if not V and not Fishing.Flags.AutoFarmSecretBoss then\n            Fishing.BossFarm.CurrentTarget = nil\n            Fishing.BossFarm.CurrentType = nil\n            Fishing.BossFarm.CurrentToken = nil\n            Fishing.BossFarm.HasHooked = false\n            Fishing.BossFarm.PendingCancel = false\n            Fishing.BossFarm.CurrentRunId = Fishing.BossFarm.CurrentRunId + 1\n        end\n    end })\n    Cfg.register(FarmSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Farm Secret Boss\", { Name = \"Auto Farm Secret Boss\", Default = false, Callback = function(V)\n        Fishing.Flags.AutoFarmSecretBoss = V\n        if V then Fishing.Flags.AutoCast = false end\n        if not V and not Fishing.Flags.AutoFarmBoss then\n            Fishing.BossFarm.CurrentTarget = nil\n            Fishing.BossFarm.CurrentType = nil\n            Fishing.BossFarm.CurrentToken = nil\n            Fishing.BossFarm.HasHooked = false\n            Fishing.BossFarm.PendingCancel = false\n            Fishing.BossFarm.CurrentRunId = Fishing.BossFarm.CurrentRunId + 1\n        end\n    end })), \"Toggle\", \"Auto Farm Secret Boss\", { Name = \"Auto Farm Secret Boss\", Default = false, Callback = function(V)\n        Fishing.Flags.AutoFarmSecretBoss = V\n        if V then Fishing.Flags.AutoCast = false end\n        if not V and not Fishing.Flags.AutoFarmBoss then\n            Fishing.BossFarm.CurrentTarget = nil\n            Fishing.BossFarm.CurrentType = nil\n            Fishing.BossFarm.CurrentToken = nil\n            Fishing.BossFarm.HasHooked = false\n            Fishing.BossFarm.PendingCancel = false\n            Fishing.BossFarm.CurrentRunId = Fishing.BossFarm.CurrentRunId + 1\n        end\n    end })\n    Cfg.register(FarmSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Sell Fish\", { Name = \"Auto Sell Fish\", Default = false, Callback = function(V) MiscFlags.AutoSell = V end })), \"Toggle\", \"Auto Sell Fish\", { Name = \"Auto Sell Fish\", Default = false, Callback = function(V) MiscFlags.AutoSell = V end })\n    Cfg.register(FarmSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Method Sell #1\", {\n        Name = \"Method Sell #1\",\n        Options = {\"Spam\", \"When full\"},\n        Default = \"Spam\",\n        Callback = function(value) NexusState.sellMethod1 = value end\n    })), \"Dropdown\", \"Method Sell #1\", {\n        Name = \"Method Sell #1\",\n        Options = {\"Spam\", \"When full\"},\n        Default = \"Spam\",\n        Callback = function(value) NexusState.sellMethod1 = value end\n    })\n    Cfg.register(FarmSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Method Sell #2\", {\n        Name = \"Method Sell #2\",\n        Options = {\"Instant\", \"Teleport\"},\n        Default = \"Instant\",\n        Callback = function(value) NexusState.sellMethod2 = value end\n    })), \"Dropdown\", \"Method Sell #2\", {\n        Name = \"Method Sell #2\",\n        Options = {\"Instant\", \"Teleport\"},\n        Default = \"Instant\",\n        Callback = function(value) NexusState.sellMethod2 = value end\n    })\n\n    local autoBossEnabled = {\n        Enzo = Fishing.Flags.AutoFightEnzo == true,\n        [\"Long Diaohai\"] = Fishing.Flags.AutoFightLongDiaohai == true,\n        [\"Black Tortoise Bloodline\"] = false,\n    }\n    local autoBossThreads = {}\n\n    local function isLocalPlayerInBossFight()\n        local active = false\n        pcall(function()\n            local pg = LocalPlayer:FindFirstChild(\"PlayerGui\")\n            local mg = (MainGui and MainGui.Parent and MainGui) or (pg and pg:FindFirstChild(\"MainGui\"))\n            local fishing = mg and mg:FindFirstChild(\"Fishing\")\n            if fishing and fishing.Visible == true then\n                local bossBar = fishing:FindFirstChild(\"BossFightBar\")\n                if bossBar and bossBar.Visible == true then active = true return end\n                local rhythm = fishing:FindFirstChild(\"Rhythm\")\n                if rhythm and rhythm.Visible == true then active = true return end\n            end\n        end)\n        return active\n    end\n\n    local function getStartBossFightRemote()\n        local rs = game:GetService(\"ReplicatedStorage\")\n        local rsEvents = rs and rs:FindFirstChild(\"Events\")\n        local ev = (rsEvents and rsEvents:FindFirstChild(\"StartBossFight\"))\n            or (Events and typeof(Events) == \"Instance\" and Events.Parll.running then\n                    NexusState.Reroll.running = false\n                    if NexusState.Reroll.thread then\n                        task.cancel(NexusState.Reroll.thread)\n                        NexusState.Reroll.thread = nil\n                    end\n                    if NexusState.Reroll.teleported and NexusState.Reroll.oldPosition then\n                        local char = LocalPlayer.Character\n                        if char then\n                            local root = char:FindFirstChild(\"HumanoidRootPart\")\n                            if root then\n                                root.CFrame = CFrame.new(NexusState.Reroll.oldPosition)\n                                NexusState.Reroll.oldPosition = nil\n                                NexusState.Reroll.teleported = false\n                            end\n                        end\n                    end\n                    NexusLib:Notify({ Title = \"Reroll\", Message = \"Stopped\", Duration = 2 })\n                    return\n                end\n\n                local skillName = selectedSkillForReroll\n                local targetTrait = selectedTargetTrait\n                if not skillName or skillName == \"\" or skillName == \"No skill owned\" then\n                    NexusLib:Notify({ Title = \"Reroll\", Message = \"Select a valid skill\", Duration = 2 })\n                    return\n                end\n                if not targetTrait or targetTrait == \"\" or targetTrait == \"No trait available\" then\n                    NexusLib:Notify({ Title = \"Reroll\", Message = \"Select a target trait\", Duration = 2 })\n                    return\n                end\n                if not RerollTrait then\n                    NexusLib:Notify({ Title = \"Reroll\", Message = \"RerollTrait event not found\", Duration = 2 })\n                    return\n                end\n                local p = Data and Data:FindFirstChild(tostring(LocalPlayer.UserId))\n                local rerollCount = p and p:FindFirstChild(\"Trait Reroll\")\n                if rerollCount and rerollCount.Value <= 0 then\n                    NexusLib:Notify({ Title = \"Reroll\", Message = \"No rerolls left!\", Duration = 2 })\n                    return\n                end\n\n                NexusState.Reroll.teleported = false\n                NexusState.Reroll.oldPosition = nil\n                if NexusState.Reroll.method == \"Teleport\" then\n                    local npc = Workspace:FindFirstChild(\"NPC\")\n                    if npc then\n                        local func = npc:FindFirstChild(\"Function\")\n                        if func then\n                            local nanjiang = func:FindFirstChild(\"Nanjiang\")\n                            if typeof(nanjiang) == \"Instance\" and nanjiang:IsA(\"Model\") then\n                                local hrp = nanjiang:FindFirstChild(\"HumanoidRootPart\")\n                                if hrp then\n                                    local char = LocalPlayer.Character\n                                    if char then\n                                        local root = char:FindFirstChild(\"HumanoidRootPart\")\n                                        if root then\n                                            NexusState.Reroll.oldPosition = root.Position\n                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                            NexusState.Reroll.teleported = true\n                                            task.wait(0.3)\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                    end\n                    if not NexusState.Reroll.teleported then\n                        NexusLib:Notify({ Title = \"Reroll\", Message = \"Could not find Nanjiang, teleport failed. Continuing anyway.\", Duration = 3 })\n                    end\n                end\n\n                NexusState.Reroll.running = true\n                NexusLib:Notify({ Title = \"Reroll\", Message = \"Reroll started... Target: \" .. targetTrait, Duration = 2 })\n\n                NexusState.Reroll.thread = task.spawn(function()\n                    local successCount = 0\n                    while NexusState.Reroll.running do\n                        local p2 = Data and Data:FindFirstChild(tostring(LocalPlayer.UserId))\n                        local count = p2 and p2:FindFirstChild(\"Trait Reroll\")\n                        if count and count.Value <= 0 then\n                            NexusLib:Notify({ Title = \"Reroll\", Message = \"No rerolls left, stopping\", Duration = 2 })\n                            break\n                        end\n                        local success, result = pcall(function()\n                            return RerollTrait:InvokeServer(skillName, ignoreLocked)\n                        end)\n                        if not success or not result then\n                            NexusLib:Notify({ Title = \"Reroll\", Message = \"Reroll failed, stopping\", Duration = 2 })\n                            break\n                        end\n                        successCount = successCount + 1\n                        local traitName = result.Name\n                        if traitName == targetTrait then\n                            NexusLib:Notify({ Title = \"Reroll\", Message = \"Got \" .. targetTrait .. \" on \" .. skillName .. \" after \" .. successCount .. \" rerolls!\", Duration = 3 })\n                            break\n                        end\n                        task.wait(0.15)\n                    end\n\n                    if NexusState.Reroll.teleported and NexusState.Reroll.oldPosition then\n                        local char = LocalPlayer.Character\n                        if char then\n                            local root = char:FindFirstChild(\"HumanoidRootPart\")\n                            if root then\n                                root.CFrame = CFrame.new(NexusState.Reroll.oldPosition)\n                                NexusState.Reroll.oldPosition = nil\n                                NexusState.Reroll.teleported = false\n                            end\n                        end\n                    end\n                    NexusState.Reroll.running = false\n                    NexusState.Reroll.thread = nil\n                    NexusLib:Notify({ Title = \"Reroll\", Message = \"Stopped\", Duration = 2 })\n                end)\n            end\n        })\n    end\n\n    -- Craft Bait\n    do\n        local CraftSection = ShopTab:CreateSection(\"Craft Bait\")\n        Cfg.register(CraftSection:CreateTextbox(Cfg.wrap(\"Textbox\", \"Number of baits to craft\", {\n            Name = \"Number of baits to craft\",\n            Placeholder = \"1\",\n            Default = \"1\",\n            Callback = function(value)\n                local num = tonumber(value)\n                if num and num >= 1 then\n                    NexusState.craftBaitQuantity = math.floor(num)\n                else\n                    NexusState.craftBaitQuantity = 1\n                end\n            end\n        })), \"Textbox\", \"Number of baits to craft\", {\n            Name = \"Number of baits to craft\",\n            Placeholder = \"1\",\n            Default = \"1\",\n            Callback = function(value)\n                local num = tonumber(value)\n                if num and num >= 1 then\n                    NexusState.craftBaitQuantity = math.floor(num)\n                else\n                    NexusState.craftBaitQuantity = 1\n                end\n            end\n        })\n\n        Cfg.register(CraftSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Choose a Bait\", {\n            Name = \"Choose a Bait\",\n            Options = {\"Rainbow Bait\", \"Frost Bait\", \"Nameless Bait\"},\n            Default = \"Rainbow Bait\",\n            Callback = function(value) NexusState.craftBaitName = value end\n        })), \"Dropdown\", \"Choose a Bait\", {\n            Name = \"Choose a Bait\",\n            Options = {\"Rainbow Bait\", \"Frost Bait\", \"Nameless Bait\"},\n            Default = \"Rainbow Bait\",\n            Callback = function(value) NexusState.craftBaitName = value end\n        })\n\n        Cfg.register(CraftSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Craft Method\", {\n            Name = \"Craft Method\",\n            Options = {\"Instant\", \"Teleport\"},\n            Default = \"Instant\",\n            Callback = function(value) NexusState.craftBaitMethod = value end\n        })), \"Dropdown\", \"Craft Method\", {\n            Name = \"Craft Method\",\n            Options = {\"Instant\", \"Teleport\"},\n            Default = \"Instant\",\n            Callback = function(value) NexusState.craftBaitMethod = value end\n        })\n\n        local BAIT_RECIPES = {\n            [\"Rainbow Bait\"] = {\n                {name = \"Colossal Tigerfish\", minKg = 3000000, maxKg = 6000000},\n                {name = \"Heavenpiercer Turtle\", minKg = 3000000, maxKg = 6000000},\n                {name = \"Golden Guardian Fish\", minKg = 1000000, maxKg = 3000000},\n                {name = \"Crimson Electric Eel\", minKg = 3000000, maxKg = 4000000},\n            },\n            [\"Frost Bait\"] = {\n                {name = \"Frost Kingfish\", minKg = 4000000, maxKg = 7000000},\n                {name = \"Ascended Perch\", minKg = 900000, maxKg = 1000000},\n                {name = \"Primordial Kunfish Overlord\", minKg = 1000000, maxKg = 1600000},\n                {name = \"Warbringer Shark\", minKg = 500000, maxKg = 800000},\n            },\n            [\"Nameless Bait\"] = {\n                {name = \"Mountain Fish\", minKg = 1000000, maxKg = 5000000},\n                {name = \"Tiger Mirefish\", minKg = 1000000, maxKg = 3000000},\n                {name = \"Mirage Lanternfish\", minKg = 3000000, maxKg = 5000000},\n                {name = \"Octoparasitic Fish\", minKg = 3000000, maxKg = 5000000},\n            }\n        }\n\n        local function checkMaterials(baitName, quantity)\n            local recipe = BAIT_RECIPES[baitName]\n            if not recipe then return false, \"No recipe found for \" .. baitName end\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not userData then return false, \"Player data not found\" end\n            local inventory = userData:FindFirstChild(\"Inventory\")\n            if not inventory then return false, \"Inventory not found\" end\n            local fishCount = {}\n            for _, req in ipairs(recipe) do fishCount[req.name] = 0 end\n            for _, item in pairs(inventory:GetChildren()) do\n                local fishName, weight, count = parseCraftFishEntry(item)\n                if fishName and fishName ~= \"\" then\n                    local req = nil\n                    for _, r in ipairs(recipe) do\n                        if r.name == fishName then req = r; break end\n                    end\n                    if req then\n                        if weight and weight >= req.minKg and weight <= req.maxKg then\n                            fishCount[req.name] = fishCount[req.name] + count\n                        end\n                    end\n                end\n            end\n            local missing = {}\n            for _, req in ipairs(recipe) do\n                local count = fishCount[req.name] or 0\n                if count < quantity then\n                    table.insert(missing, req.name .. \" (can \" .. quantity .. \", co \" .. count .. \")\")\n                end\n            end\n            if #missing > 0 then\n                return false, \"Missing materials: \" .. table.concat(missing, \", \")\n            end\n            return true, \"Materials are sufficient!\"\n        end\n\n        local function craftBait()\n            local qty = NexusState.craftBaitQuantity\n            local ok, msg = checkMaterials(NexusState.craftBaitName, qty)\n            if not ok then\n                NexusLib:Notify({ Title = \"CrbirthThread then\n                    task.cancel(NexusState.autoRebirthThread)\n                    NexusState.autoRebirthThread = nil\n                end\n                if NexusState.upgradeCharacter.teleported and NexusState.upgradeCharacter.oldPosition then\n                    local char = LocalPlayer.Character\n                    if char then\n                        local root = char:FindFirstChild(\"HumanoidRootPart\")\n                        if root then\n                            root.CFrame = CFrame.new(NexusState.upgradeCharacter.oldPosition)\n                            NexusState.upgradeCharacter.oldPosition = nil\n                            NexusState.upgradeCharacter.teleported = false\n                        end\n                    end\n                end\n                NexusLib:Notify({ Title = \"Auto Rebirth\", Message = \"Stopped\", Duration = 2 })\n            end\n        end\n    })\n\n    local function displayStats()\n        local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n        if not userData then return end\n        local cash = userData:FindFirstChild(\"Cash\") and userData.Cash.Value or 0\n        local level = userData:FindFirstChild(\"Level\") and userData.Level:FindFirstChild(\"Level\") and userData.Level.Level.Value or 0\n        local crystal = userData:FindFirstChild(\"Crystal\") and userData.Crystal.Value or 0\n        local ticket = userData:FindFirstChild(\"Ticket\") and userData.Ticket.Value or 0\n        NexusLib:Notify({\n            Title = \"Resources\",\n            Message = string.format(\"Cash: %.2fB | Level: %d | Crystal: %d | Ticket: %d\", cash/1e9, level, crystal, ticket),\n            Duration = 4\n        })\n    end\n    UpgradeSection:CreateButton({ Name = \"Check Resources\", Callback = displayStats })\nend\n\n-- ============================================================\n-- ===== TELEPORT TAB =====\n-- ============================================================\ndo\n    local TeleportTab = Window:CreateTab(\"Teleport\")\n    local TPSection = TeleportTab:CreateSection(\"NPC & Weather\", \"Left\")\n\n    TPSection:CreateButton({\n        Name = \"TP to Taoist\",\n        Callback = function()\n            local taoist = nil\n            for _, v in pairs(Workspace:GetDescendants()) do\n                if typeof(v) == \"Instance\" and typeof(v) == \"Instance\" and v:IsA(\"Model\") and string.find(v.Name:lower(), \"taoist\") and v:FindFirstChild(\"HumanoidRootPart\") then\n                    taoist = v\n                    break\n                end\n            end\n            if taoist and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\") then\n                LocalPlayer.Character.HumanoidRootPart.CFrame = taoist.HumanoidRootPart.CFrame * CFrame.new(0, 0, 4)\n                NexusLib:Notify({ Title = \"Taoist\", Message = \"Teleported!\", Duration = 3 })\n            else\n                NexusLib:Notify({ Title = \"Taoist\", Message = \"Not found!\", Duration = 3 })\n            end\n        end\n    })\n\n    TPSection:CreateButton({\n        Name = \"TP to Maoshan\",\n        Callback = function()\n            local maoshan = nil\n            for _, v in pairs(Workspace:GetDescendants()) do\n                if typeof(v) == \"Instance\" and typeof(v) == \"Instance\" and v:IsA(\"Model\") and (string.find(v.Name:lower(), \"maoshan\") or string.find(v.Name:lower(), \"merchant\")) and v:FindFirstChild(\"HumanoidRootPart\") then\n                    maoshan = v\n                    break\n                end\n            end\n            if maoshan and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\") then\n                LocalPlayer.Character.HumanoidRootPart.CFrame = maoshan.HumanoidRootPart.CFrame * CFrame.new(0, 0, 4)\n                NexusLib:Notify({ Title = \"Maoshan\", Message = \"Teleported!\", Duration = 3 })\n            else\n                NexusLib:Notify({ Title = \"Maoshan\", Message = \"Not found!\", Duration = 3 })\n            end\n        end\n    })\n\n    TPSection:CreateButton({\n        Name = \"TP to Spirit\",\n        Callback = function()\n            local godFolder = Workspace:FindFirstChild(\"NPC\") and Workspace.NPC:FindFirstChild(\"God\")\n            if not godFolder then\n                NexusLib:Notify({ Title = \"Spirit\", Message = \"Folder God not found!\", Duration = 3 })\n                return\n            end\n            local target = nil\n            for _, child in pairs(godFolder:GetChildren()) do\n                if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"Model\") then\n                    local hrp = child:FindFirstChild(\"HumanoidRootPart\")\n                    if hrp then\n                        target = hrp\n                        break\n                    end\n                elseif typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"BasePart\") then\n                    target = child\n                    break\n                end\n            end\n            if not target then\n                NexusLib:Notify({ Title = \"Spirit\", Message = \"No Spirit found!\", Duration = 3 })\n                return\n            end\n            local char = LocalPlayer.Character\n            if not char then return end\n            local hrp = char:FindFirstChild(\"HumanoidRootPart\")\n            if hrp then\n                hrp.CFrame = target.CFrame + Vector3.new(0, 3, 0)\n                NexusLib:Notify({ Title = \"Spirit\", Message = \"Teleported to Spirit!\", Duration = 3 })\n            end\n        end\n    })\n\n    -- ===== NPC TELEPORT + GIVE FISH (Duan Gan / Dumb guy) =====\n    do\n        local GiveSection = TeleportTab:CreateSection(\"Quest NPC & Give Fish\", \"Right\")\n\n        local function npcRoot()\n            return Workspace:FindFirstChild(\"NPC\")\n        end\n\n        local function findNpcHrp(npcName)\n            local hrp = nil\n            pcall(function()\n                local npcFolder = npcRoot()\n                if not npcFolder then return end\n                local f = npcFolder:FindFirstChild(\"Function\")\n                local m = (f and f:FindFirstChild(npcName)) or npcFolder:FindFirstChild(npcName)\n                if m then hrp = m:FindFirstChild(\"HumanoidRootPart\") or m:FindFirstChild(\"Torso\") end\n            end)\n            return hrp\n        end\n\n        local function teleportNearNpc(npcName, offset)\n            local hrp = findNpcHrp(npcName)\n            local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n            if not hrp or not root then return false end\n            pcall(function()\n                root.CFrame = CFrame.new(hrp.Position + (offset or Vector3.new(0, 3, 0)))\n            end)\n            return true\n        end\n\n        local function parseWeightKg(text)\n            local clean = string.gsub(text, \"[,%s]\", \"\")\n            local num, suffix = string.match(clean, \"(%d+%.?%d*)([KkMmBbTt]?)\")\n            local n = tonumber(num) or 0\n            if suffix == \"K\" or suffix == \"k\" then\n                n = n * 1000\n            elseif suffix == \"M\" or suffix == \"m\" then\n                n = n * 1000000\n            elseif suffix == \"B\" or suffix == \"b\" then\n                n = n * 1000000000\n            elseif suffix == \"T\" or suffix == \"t\" then\n                n = n * 1000000000000\n            end\n            return n\n        end\n\n        local function getFishKg(item)\n            local w = 0\n            pcall(function()\n                local attr = item:GetAttribute(\"Weight\")\n                if tonumber(attr) and tonumber(attr) > 0 then\n                    w = tonumber(attr)\n                    return\n                end\n                local fishName = tostring(item.Name or \"\")\n                local parts = {}\n                for part in string.gmatch(fishName, \"[^|]+\") do table.insert(parts, part) end\n                if #parts >= 2 then\n                    w = parseWeightKg(parts[2])\n                elseif item:IsA(\"StringValue\") then\n                    local valueParts = {}\n                    for part in string.gmatch(tostring(item.Value or \"\"), \"[^|]+\") do\n                        table.insert(valueParts, part)\n                    end\n                    if #valueParts >= 2 then w = parseWeightKg(valueParts[2]) end\n                end\n            end)\n            return w\n        end\n\n        local function collectBigFish(minKg)\n            local out = {}\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            local inv = userData and userData:FindFirstChild(\"Inventory\")\n            if not inv then return out end\n            for _, item in pairs(inv:GetChildren()) do\n                local kg = getFishKg(item)\n                if kg > minKg then\n                    table.insert(out, { item = item, name = item.Name, kg = kg })\n                end\n            end\n            table.sort(out, function(a, b) return a.kg < b.kg end)\n            return out\n        end\n\n        local function equipFishForGive(entry)\n            local moveItems = Events:FindFirstChild(\"MoveItems\")\n            local toggleHotbar = Events:FindFirstChild(\"ToggleHotbar\")\n            if not moveItems or not toggleHotbar or not entry or not entry.item then return false end\n            local moved = pcall(function()\n                moveItems:FireServer(\"Inventory\", entry.item.Name, \"4\")\n            end)\n            if not moved then return false end\n            task.wait(0.35)\n            local callOk, serverResult = pcall(function()\n                if toggleHotbar:IsA(\"RemoteFunction\") then\n                    return toggleHotbar:InvokeServer(\"4\", nil)\n                end\n                toggleHotbar:FireServer(\"4\", nil)\n                return true\n            end)\n            task.wait(0.35)\n            return callOk and serverResult ~= false\n        end\n\n        local function giveFishToDumbGuy(entry)\n            if not entry or not entry.item or (entry.kg or 0) <= 2000000 then return false end\n            local model = nil\n            pcall(function()\n                local npcFolder = Workspace:FindFirstChild(\"NPC\")\n                local f = npcFolder and npcFolder:FindFirstChild(\"Function\")\n                model = f and f:FindFirstChild(\"Dumb guy\")\n            end)\n            if not model or not equipFishForGive(entry) then return false end\n            local chooseDialogue = Events:FindFirstChild(\"ChooseDialogueOption\")\n            if not chooseDialogue then return false end\n            for _ = 1, 3 do\n                local sent = pcall(function()\n                    chooseDialogue:FireServer(\"Dumb guy\", 1, \"GiveFish\", { model })\n                end)\n                if sent then return true end\n                task.wait(0.25)\n            end\n            return false\n        end\n\n        GiveSection:CreateButton({\n            Name = \"Teleport To Duan Gan NPC\",\n            Callback = function()\n                if teleportNearNpc(\"Duan Gan\", Vector3.new(0, 3, 0)) then\n                    NexusLib:Notify({ Title = \"Duan Gan\", Message = \"Teleported!\", Duration = 3 })\n                else\n                    NexusLib:Notify({ Title = \"Duan Gan\", Message = \"NPC not found!\", Duration = 3 })\n                end\n            end\n        })\n\n        GiveSection:CreateButton({\n            Name = \"Teleport To Dumb Guy NPC\",\n            Callback = function()\n                if teleportNearNpc(\"Dumb guy\", Vector3.new(0, 3, 0)) then\n                    NexusLib:Notify({ Title = \"Dumb Guy\", Message = \"Teleported!\", Duration = 3 })\n                else\n                    NexusLib:Notify({ Title = \"Dumb Guy\", Message = \"NPC not found!\", Duration = 3 })\n                end\n            end\n        })\n\n        GiveSection:CreateButton({\n            Name = \"Give 1 Fish > 2M kg\",\n     npcDropdown = NpcSection:CreateDropdown({\n            Name = \"Misc NPCs\",\n            Options = npcList,\n            Default = selectedNpc,\n            Callback = function(value)\n                selectedNpc = value\n            end\n        })\n        \n        -- Teleport to selected NPC button\n        NpcSection:CreateButton({\n            Name = \"Teleport to selected NPC\",\n            Callback = function()\n                if not selectedNpc or selectedNpc == \"No NPCs found\" then\n                    NexusLib:Notify({ Title = \"NPC Teleport\", Message = \"No NPC selected!\", Duration = 2 })\n                    return\n                end\n                \n                local funcFolder = workspace:FindFirstChild(\"NPC\") and workspace.NPC:FindFirstChild(\"Function\")\n                if not funcFolder then\n                    NexusLib:Notify({ Title = \"NPC Teleport\", Message = \"NPC.Function folder not found!\", Duration = 2 })\n                    return\n                end\n                \n                local targetModel = nil\n                for _, child in ipairs(funcFolder:GetDescendants()) do\n                    if typeof(child) == \"Instance\" and child:IsA(\"Model\") and child.Name == selectedNpc and child.Parent and typeof(child.Parent) == \"Instance\" and child.Parent:IsA(\"Folder\") then\n                        targetModel = child\n                        break\n                    end\n                end\n                \n                if not targetModel then\n                    NexusLib:Notify({ Title = \"NPC Teleport\", Message = \"NPC not found!\", Duration = 2 })\n                    return\n                end\n                \n                local hrp = targetModel:FindFirstChild(\"HumanoidRootPart\") or targetModel.PrimaryPart\n                if not hrp then\n                    hrp = targetModel:FindFirstChildWhichIsA(\"BasePart\")\n                end\n                if not hrp then\n                    NexusLib:Notify({ Title = \"NPC Teleport\", Message = \"Cannot find part to teleport to!\", Duration = 2 })\n                    return\n                end\n                \n                local myChar = LocalPlayer.Character\n                if not myChar then return end\n                local myHrp = myChar:FindFirstChild(\"HumanoidRootPart\")\n                if not myHrp then return end\n                \n                myHrp.CFrame = hrp.CFrame + Vector3.new(0, 3, 0)\n                \n                NexusLib:Notify({ Title = \"NPC Teleport\", Message = \"Teleported to \" .. selectedNpc, Duration = 2 })\n            end\n        })\n        -- ===== LEARN SKILL NPC =====\n        local selectedLearnNpc = \"Sage Yijiu\"\n        \n        -- Dropdown with a single option\n        local learnDropdown = Cfg.register(NpcSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Learn Skill NPC\", {\n            Name = \"Learn Skill NPC\",\n            Options = {\"Sage Yijiu\"},\n            Default = \"Sage Yijiu\",\n            Callback = function(value)\n                selectedLearnNpc = value\n            end\n        })), \"Dropdown\", \"Learn Skill NPC\", {\n            Name = \"Learn Skill NPC\",\n            Options = {\"Sage Yijiu\"},\n            Default = \"Sage Yijiu\",\n            Callback = function(value)\n                selectedLearnNpc = value\n            end\n        })\n        \n        -- Teleport to selected NPC button\n        NpcSection:CreateButton({\n            Name = \"Teleport to selected NPC\",\n            Callback = function()\n                local targetModel = workspace:FindFirstChild(\"NPC\") \n                    and workspace.NPC:FindFirstChild(\"LearnSkill\") \n                    and workspace.NPC.LearnSkill:FindFirstChild(\"Sage Yijiu\")\n                \n                if not targetModel then\n                    NexusLib:Notify({ Title = \"Learn Skill\", Message = \"Sage Yijiu not found!\", Duration = 2 })\n                    return\n                end\n                \n                local hrp = targetModel:FindFirstChild(\"HumanoidRootPart\") or targetModel.PrimaryPart\n                if not hrp then\n                    hrp = targetModel:FindFirstChildWhichIsA(\"BasePart\")\n                end\n                if not hrp then\n                    NexusLib:Notify({ Title = \"Learn Skill\", Message = \"Cannot find part to teleport to!\", Duration = 2 })\n                    return\n                end\n                \n                local myChar = LocalPlayer.Character\n                if not myChar then return end\n                local myHrp = myChar:FindFirstChild(\"HumanoidRootPart\")\n                if not myHrp then return end\n                \n                myHrp.CFrame = hrp.CFrame + Vector3.new(0, 3, 0)\n                \n                NexusLib:Notify({ Title = \"Learn Skill\", Message = \"Teleported to Sage Yijiu\", Duration = 2 })\n            end\n        })\n        -- ===== SECRET RODS SECTION =====\n        -- Secret Rod list (models parented to a Folder under workspace.SecretRod)\n        local function getSecretRodList()\n            local rods = {}\n            local secretRodFolder = workspace:FindFirstChild(\"SecretRod\")\n            if not secretRodFolder then return rods end\n            \n            for _, child in ipairs(secretRodFolder:GetDescendants()) do\n                if typeof(child) == \"Instance\" and child:IsA(\"Model\") and child.Parent and typeof(child.Parent) == \"Instance\" and child.Parent:IsA(\"Folder\") then\n                    table.insert(rods, child.Name)\n                end\n            end\n            return rods\n        end\n        \n        local rodList = getSecretRodList()\n        if #rodList == 0 then\n            table.insert(rodList, \"No Secret Rods found\")\n        end\n        \n        local selectedRod = rodList[1]\n        \n        -- Dropdown\n        local rodDropdown = NpcSection:CreateDropdown({\n            Name = \"Secret Rods\",\n            Options = rodList,\n            Default = selectedRod,\n            Callback = function(value)\n                selectedRod = value\n            end\n        })\n        \n        -- Teleport button\n        NpcSection:CreateButton({\n            Name = \"Teleport to selected Secret Rod\",\n            Callback = function()\n                if not selectedRod or selectedRod == \"No Secret Rods found\" then\n                    NexusLib:Notify({ Title = \"Secret Rod\", Message = \"No Secret Rod selected!\", Duration = 2 })\n                    return\n                end\n                \n                local secretRodFolder = workspace:FindFirstChild(\"SecretRod\")\n                if not secretRodFolder then\n                    NexusLib:Notify({ Title = \"Secret Rod\", Message = \"SecretRod folder not found!\", Duration = 2 })\n                    return\n                end\n                \n                local targetModel = nil\n                for _, child in ipairs(secretRodFolder:GetDescendants()) do\n                    if typeof(child) == \"Instance\" and child:IsA(\"Model\") and child.Name == selectedRod and child.Parent and typeof(child.Parent) == \"Instance\" and child.Parent:IsA(\"Folder\") then\n                        targetModel = child\n                        break\n                    end\n                end\n                \n                if not targetModel then\n                    NexusLib:Notify({ Title = \"Secret Rod\", Message = \"Secret Rod not found!\", Duration = 2 })\n                    return\n                end\n                \n                local hrp = targetModel:FindFirstChild(\"HumanoidRootPart\") or targetModel.PrimaryPart\n                if not hrp then\n                    hrp = targetModel:FindFirstChildWhichIsA(\"BasePart\")\n                end\n                if not hrp then\n                    NexusLib:Notify({ Title = \"Secret Rod\", Message = \"Cannot find part to teleport to!\", Duration = 2 })\n                    return\n                end\n                \n                local myChar = LocalPlayer.Character\n                if not myChar then return end\n                local myHrp = myChar:FindFirstChild(\"HumanoidRootPart\")\n                if not myHrp then return end\n                \n                myHrp.CFrame = hrp.CFrame + Vector3.new(0, 3, 0)\n                \n                NexusLib:Notify({ Title = \"Secret Rod\", Message = \"Teleported to \" .. selectedRod, Duration = 2 })\n            end\n        })\n    end\nend\n\n-- ============================================================\n-- ===== SETTINGS TAB =====\n-- ============================================================\ndo\n    local SettingsTab = Window:CreateTab(\"Settings\")\n\n    -- ===== CONFIG SECTION (save / load / auto-load / import-export) =====\n    do\n        local CfgUI = SettingsTab:CreateSection(\"Config\")\n        local Cfg = runtimeEnv.NexusConfig\n\n        CfgUI:CreateButton({\n            Name = \"Save Config\",\n            Callback = function() Cfg.save() end,\n        })\n\n        CfgUI:CreateButton({\n            Name = \"Load Config\",\n            Callback = function() Cfg.load() end,\n        })\n\n        CfgUI:CreateToggle({\n            Name = \"Auto Load Config\",\n            Default = false,\n            Callback = function(value)\n                if not (writefile and isfile) then\n                    NexusLib:Notify({ Title = \"Config\", Message = \"This executor cannot save files.\", Duration = 3 })\n                    return\n                end\n                if value then\n                    Cfg.save(Cfg.AUTO_FILE)\n                else\n                    pcall(function()\n                        if isfile(Cfg.AUTO_FILE) and delfile then delfile(Cfg.AUTO_FILE) end\n                    end)\n                end\n            end,\n        })\n\n        CfgUI:CreateButton({\n            Name = \"Export Config (Copy Code)\",\n            Callback = function() Cfg.exportCode() end,\n        })\n\n        local importBox = CfgUI:CreateTextbox({\n            Name = \"Import Config Code\",\n            Placeholder = \"Paste code, then press Import\",\n            Default = \"\",\n            Callback = function() end,\n        })\n\n        CfgUI:CreateButton({\n            Name = \"Import Config\",\n            Callback = function()\n                local code = \"\"\n                pcall(function() code = importBox.Get() end)\n                Cfg.importCode(code)\n            end,\n        })\n    end\n    local CharSection = SettingsTab:CreateSection(\"Character\")\n\n    Cfg.register(CharSection:CreateTextbox(Cfg.wrap(\"Textbox\", \"Walk Speed\", { Name = \"Walk Speed\", Placeholder = \"16\", Default = \"16\", Callback = function(V)\n        pcall(function() LocalPlayer.Character.Humanoid.WalkSpeed = tonumber(V) or 16 end)\n    end })), \"Textbox\", \"Walk Speed\", { Name = \"Walk Speed\", Placeholder = \"16\", Default = \"16\", Callback = function(V)\n        pcall(function() LocalPlayer.Character.Humanoid.WalkSpeed = tonumber(V) or 16 end)\n    end })\n\n    local function startFly()\n        local c = LocalPlayer.Character\n        if not c or not c:FindFirstChild(\"HumanoidRootPart\") then return end\n        if NexusState.flying then return end\n        if NexusState.bg then NexusState.bg:Destroy() end\n        if NexusState.bv then NexusState.bv:Destroy() end\n        local h = c.HumanoidRootPart\n        NexusState.bg = Instance.new(\"BodyGyro\", h)\n        NexusState.bg.P = 9e4\n        NexusState.bg.maxTorque = Vector3.new(9e9,9e9,9e9)\n        NexusState.bg.cframe = h.CFrame\n        NexusState.bv = Instance.new(\"BodyVelocity\", h)\n        NexusState.bv.velocity = Vector3.new(0,0,0)\n        NexusState.bv.maxForce = Vector3.new(9e9,9e9,9e9)\n        NexusState.flying = true\n        local humanoid = c:FindFirstChildOfClass(\"Humanoid\")\n        if humanoid then humanoid.PlatformStand = true end\n        if NexusState.flyInputConnection then NexusState.flyInputConnection:Disconnect() end\n        if NexusState.flyInputEndConnection then Nexualue then\n                NexusLib:Notify({ Title = \"Auto Equip\", Message = \"Best bait will be equipped automatically\", Duration = 2 })\n            else\n                NexusLib:Notify({ Title = \"Auto Equip\", Message = \"Disabled\", Duration = 2 })\n            end\n        end\n    })), \"Toggle\", \"Auto Equip Best Bait\", {\n        Name = \"Auto Equip Best Bait\",\n        Default = false,\n        Callback = function(value)\n            MiscFlags.AutoEquipBait = value\n            if value then\n                NexusLib:Notify({ Title = \"Auto Equip\", Message = \"Best bait will be equipped automatically\", Duration = 2 })\n            else\n                NexusLib:Notify({ Title = \"Auto Equip\", Message = \"Disabled\", Duration = 2 })\n            end\n        end\n    })\n\n    Cfg.register(EquipSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Equip Fishing Rod (Slot 1)\", {\n        Name = \"Auto Equip Fishing Rod (Slot 1)\",\n        Default = false,\n        Callback = function(value)\n            MiscFlags.AutoEquipRod = value\n            if value then\n                NexusLib:Notify({ Title = \"Auto Equip Rod\", Message = \"Will equip rod if not holding\", Duration = 2 })\n            else\n                NexusLib:Notify({ Title = \"Auto Equip Rod\", Message = \"Disabled\", Duration = 2 })\n            end\n        end\n    })), \"Toggle\", \"Auto Equip Fishing Rod (Slot 1)\", {\n        Name = \"Auto Equip Fishing Rod (Slot 1)\",\n        Default = false,\n        Callback = function(value)\n            MiscFlags.AutoEquipRod = value\n            if value then\n                NexusLib:Notify({ Title = \"Auto Equip Rod\", Message = \"Will equip rod if not holding\", Duration = 2 })\n            else\n                NexusLib:Notify({ Title = \"Auto Equip Rod\", Message = \"Disabled\", Duration = 2 })\n            end\n        end\n    })\n\n    task.spawn(function()\n        local ToggleHotbar = Events:FindFirstChild(\"ToggleHotbar\")\n        if not ToggleHotbar then return end\n        while task.wait(1) do\n            if not alive() then break end\n            if MiscFlags.AutoEquipRod then\n                pcall(function()\n                    if not isHoldingFishingRod() then\n                        ToggleHotbar:InvokeServer(\"1\", nil)\n                    end\n                end)\n            end\n        end\n    end)\n\n    EquipSection:CreateButton({\n        Name = \"Equip Best Rod\",\n        Callback = function()\n            local best = GetBestRod()\n            if best then\n                if EquipRod(best) then\n                    NexusLib:Notify({ Title = \"Equip Rod\", Message = \"Equipped best rod: \" .. best, Duration = 2 })\n                else\n                    NexusLib:Notify({ Title = \"Equip Rod\", Message = \"Failed to equip rod\", Duration = 2 })\n                end\n            else\n                NexusLib:Notify({ Title = \"Equip Rod\", Message = \"No rod available\", Duration = 2 })\n            end\n        end\n    })\n\n    EquipSection:CreateButton({\n        Name = \"Equip Best Orb\",\n        Callback = function()\n            local best = GetBestOrb()\n            if best then\n                if EquipOrb(best) then\n                    NexusLib:Notify({ Title = \"Equip Orb\", Message = \"Equipped best orb: \" .. best, Duration = 2 })\n                else\n                    NexusLib:Notify({ Title = \"Equip Orb\", Message = \"Failed to equip orb\", Duration = 2 })\n                end\n            else\n                NexusLib:Notify({ Title = \"Equip Orb\", Message = \"No orb available\", Duration = 2 })\n            end\n        end\n    })\n\n    task.spawn(function()\n        while task.wait(3) do\n            if MiscFlags.AutoEquipBait then\n                pcall(function()\n                    local userId = LocalPlayer.UserId\n                    local userData = Data:FindFirstChild(tostring(userId))\n                    if not userData then return end\n                    local equippedBaitValue = userData:FindFirstChild(\"EquippedBait\")\n                    if not equippedBaitValue then return end\n                    local currentBait = equippedBaitValue.Value or \"\"\n                    local best = GetBestBait()\n                    if best and best ~= currentBait then\n                        if EquipBait(best) then\n                            NexusLib:Notify({ Title = \"Auto Equip\", Message = \"Equipped best bait: \" .. best, Duration = 2 })\n                        end\n                    end\n                end)\n            end\n        end\n    end)\n\n    -- ===== AUTO NAMELESS OCTOPARASITE =====\n    do\n        local NAMELESS_NAME = \"Nameless Octoparasite\"\n        local RHY_LANES = { \"A\", \"S\", \"D\" }\n        local RHY_KEYS = { A = Enum.KeyCode.A, S = Enum.KeyCode.S, D = Enum.KeyCode.D }\n        local RHY_WINDOW = 0.22\n        local RHY_SPEED = 1.15 / 1.4\n        local RHY_BAR_FALLBACK = 0.85\n\n        NexusState.Nameless = {\n            Enabled = false,\n            Mode = \"Safe\",\n            RiskRate = 0,\n            Band = 0.08,\n            Lag = 0.03,\n            Active = false,\n            SignalUntil = 0,\n            Config = nil,\n            Method = nil,\n            NextPress = {},\n            Stats = { hit = 0, spam = 0 },\n        }\n        local Rhy = NexusState.Nameless\n\n        local function rhyFindNameless()\n            local roots = {}\n            local ocean = Workspace:FindFirstChild(\"Ocean\")\n            if ocean then\n                local boss = ocean:FindFirstChild(\"Boss\")\n                if boss then\n                    local fn = boss:FindFirstChild(\"FishName\")\n                    if fn then table.insert(roots, fn) end\n                    table.insert(roots, boss)\n                end\n                table.insert(roots, ocean)\n            end\n            local fishes = Workspace:FindFirstChild(\"Fishes\")\n            if fishes then table.insert(roots, fishes) end\n            for _, root in ipairs(roots) do\n                local ok, found = pcall(function() return root:FindFirstChild(NAMELESS_NAME, true) end)\n                if ok and found then return found end\n            end\n            return nil\n        end\n\n        local function rhyPivotOf(inst)\n            if not inst then return nil end\n            local ok, cf = pcall(function()\n                if typeof(inst) == \"Instance\" and typeof(inst) == \"Instance\" and inst:IsA(\"BasePart\") then return inst.CFrame end\n                if typeof(inst) == \"Instance\" and typeof(inst) == \"Instance\" and inst:IsA(\"Model\") then\n                    if inst.PrimaryPart then return inst.PrimaryPart.CFrame end\n                    return inst:GetPivot()\n                end\n                local part = inst:FindFirstChildWhichIsA(\"BasePart\", true)\n                if part then return part.CFrame end\n                return nil\n            end)\n            if ok and cf then return cf end\n            return nil\n        end\n\n        local function rhyTeleportToNameless()\n            local model = rhyFindNameless()\n            if not model then\n                NexusLib:Notify({ Title = \"Nameless\", Message = \"Cannot find \" .. NAMELESS_NAME .. \" in Workspace (boss not spawned yet?)\", Duration = 3 })\n                return false\n            end\n            local cf = rhyPivotOf(model)\n            if not cf then\n                NexusLib:Notify({ Title = \"Nameless\", Message = \"Found boss but could not get its position!\", Duration = 3 })\n                return false\n            end\n            local char = LocalPlayer.Character\n            local hrp = char and (char:FindFirstChild(\"HumanoidRootPart\") or char.PrimaryPart)\n            if not hrp then\n                NexusLib:Notify({ Title = \"Nameless\", Message = \"Character not found!\", Duration = 2 })\n                return false\n            end\n            hrp.CFrame = cf + Vector3.new(0, 12, 0)\n            NexusLib:Notify({ Title = \"Nameless\", Message = \"Teleported to \" .. NAMELESS_NAME, Duration = 2 })\n            return true\n        end\n\n        local function rhyPress(laneFrame, lane)\n            local methods = {\n                function()\n                    if not firesignal then return false end\n                    local btn = laneFrame and laneFrame:FindFirstChild(\"Button\")\n                    if not btn then return false end\n                    if not (typeof(btn) == \"Instance\" and (btn:IsA(\"TextButton\") or btn:IsA(\"ImageButton\"))) then return false end\n                    firesignal(btn.MouseButton1Click)\n                    return true\n                end,\n                function()\n                    local vim = game:GetService(\"VirtualInputManager\")\n                    vim:SendKeyEvent(true, RHY_KEYS[lane], false, game)\n                    vim:SendKeyEvent(false, RHY_KEYS[lane], false, game)\n                    return true\n                end,\n                function()\n                    local vim = game:GetService(\"VirtualInputManager\")\n                    vim:SendKeyEvent(true, RHY_KEYS[lane], false, nil)\n                    vim:SendKeyEvent(false, RHY_KEYS[lane], false, nil)\n                    return true\n                end,\n            }\n            if Rhy.Method then\n                local ok, res = pcall(methods[Rhy.Method])\n                if ok and res then return true end\n                Rhy.Method = nil\n            end\n            for i, fn in ipairs(methods) do\n                local ok, res = pcall(fn)\n                if ok and res then\n                    Rhy.Method = i\n                    return true\n                end\n            end\n            return false\n        end\n\n        local function rhyGui()\n            local fishing = MainGui and MainGui:FindFirstChild(\"Fishing\")\n            if not fishing then return nil, nil end\n            return fishing:FindFirstChild(\"Rhythm\"), fishing\n        end\n\n        local function rhyUiActive()\n            local gui, fishing = rhyGui()\n            if not gui or not fishing then return false end\n            return gui.Visible == true and fishing.Visible == true\n        end\n\n        local function rhyMaxBand()\n            local m = RHY_WINDOW - RHY_SPEED * (Rhy.Lag or 0) - 0.02\n            if m < 0.01 then m = 0.01 end\n            return m\n        end\n\n        local function rhyScan(now)\n            local gui = rhyGui()\n            if not gui then return end\n            for _, lane in ipairs(RHY_LANES) do\n                local laneFrame = gui:FindFirstChild(\"Progression\" .. lane)\n                if laneFrame then\n                    local barY = RHY_BAR_FALLBACK\n                    local barFrame = laneFrame:FindFirstChild(\"BarFrame\")\n                    if barFrame then\n                        local okB, y = pcall(function() return barFrame.Position.Y.Scale end)\n                        if okB and type(y) == \"number\" then barY = y end\n                    end\n                    local band = math.clamp(Rhy.Band, 0.01, rhyMaxBand())\n                    local inWindow = 0\n                    for _, note in ipairs(laneFrame:GetChildren()) do\n                        if note.Name == \"Note_FX\" then\n                            local okP, y = pcall(function() return note.Position.Y.Scale end)\n                            if okP and type(y) == \"number\" then\n                                if math.abs((y + RHY_SPEED * Rhy.Lag) - barY) <= band then\n                                    inWindow = inWindow + 1\n                                end\n                            end\n                        end\n                    end\n                    if inWindow > 5 then inWindow = 5 end\n                    for _ = 1, inWindow do\n                        if rhyPress(laneFrame, lane) then\n                            Rhy.Stats.hit = Rhy.Stats.hit + 1\n                        end\n                    end\n                end\n            end\n        end\n\n.Scale\n            local hbSize = hitbox.Size.X.Scale\n\n            local now = tick()\n            local dtFrame = now - lastFrameTime\n            lastFrameTime = now\n\n            if dtFrame > 0.001 and dtFrame < 0.1 then\n                local rawSpeed = (barPos - prevBarPos) / dtFrame\n                prevBarPos = barPos\n                if math.abs(rawSpeed) < 5 then\n                    currentSpeed = currentSpeed * 0.7 + rawSpeed * 0.3\n                end\n            else\n                prevBarPos = barPos\n            end\n\n            local lastInput = UserInputService:GetLastInputType()\n            local latency = (lastInput == Enum.UserInputType.Touch) and 0.06 or 0.025\n            local compensatedBarPos = barPos - (currentSpeed * latency)\n\n            local halfWidth = hbSize / 2\n            local margin = hbSize * 0.15\n\n            local badOverlap = false\n            if badBox and badBox.Visible then\n                local badPos = badBox.Position.X.Scale\n                local badHalf = badBox.Size.X.Scale / 2\n                if compensatedBarPos >= (badPos - badHalf - 0.01) and compensatedBarPos <= (badPos + badHalf + 0.01) then\n                    badOverlap = true\n                end\n            end\n\n            if not badOverlap and compensatedBarPos >= (hbPos - halfWidth + margin) and compensatedBarPos <= (hbPos + halfWidth - margin) then\n                if now - lastQTEClick > 0.18 then\n                    lastQTEClick = now\n                    local deskBtn = fishing and (fishing:FindFirstChild(\"Fishing2\") or fishing:FindFirstChild(\"Button\"))\n                    if deskBtn and deskBtn:IsA(\"GuiButton\") and firesignal then\n                        pcall(firesignal, deskBtn.MouseButton1Down)\n                    else\n                        pcall(function()\n                            local vim = game:GetService(\"VirtualInputManager\")\n                            vim:SendMouseButtonEvent(0, 0, 0, true, game, 0)\n                            task.delay(0.015, function()\n                                vim:SendMouseButtonEvent(0, 0, 0, false, game, 0)\n                            end)\n                        end)\n                    end\n                end\n            end\n        else\n            prevBarPos = 0\n            lastFrameTime = tick()\n            currentSpeed = 0\n        end\n    else\n        cachedBar = nil\n        cachedHitbox = nil\n        cachedHitboxBad = nil\n        prevBarPos = 0\n        lastFrameTime = tick()\n        currentSpeed = 0\n    end\n\n    if fishingVisible and Fishing.Flags.AnchorLock and not bossBarVisible and not Fishing.BossFarm.PendingCancel then\n        local bf = fishing:FindFirstChild(\"BarFrame\")\n        local b = bf and bf:FindFirstChild(\"Bar\")\n        if b then b.Position = UDim2.new(0.5, 0, 0.5, 0) end\n    end\n\n    if NexusState.flying and NexusState.bg and NexusState.bv and LocalPlayer.Character then\n        local h = LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n        local hum = LocalPlayer.Character:FindFirstChildOfClass(\"Humanoid\")\n        if h and hum then\n            local cameraLook = Camera.CFrame.LookVector\n            local move = hum.MoveDirection\n            local horizontal = Vector3.new(move.X, 0, move.Z)\n            local vertical = (NexusState.flyKeys.Up and 1 or 0) - (NexusState.flyKeys.Down and 1 or 0)\n            NexusState.bv.Velocity = horizontal * NexusState.flySpeed + Vector3.new(0, vertical * NexusState.flySpeed, 0)\n            local look = Vector3.new(cameraLook.X, 0, cameraLook.Z)\n            if look.Magnitude > 0.01 then\n                NexusState.bg.CFrame = CFrame.lookAt(h.Position, h.Position + look.Unit)\n            end\n        end\n    end\n\n    if MiscFlags.FullBright then\n        if not NexusState.fullBrightApplied then\n            Lighting.Ambient = Color3.new(1,1,1)\n            Lighting.ColorShift_Bottom = Color3.new(1,1,1)\n            Lighting.ColorShift_Top = Color3.new(1,1,1)\n            Lighting.Brightness = 2\n            Lighting.OutdoorAmbient = Color3.new(1,1,1)\n            NexusState.fullBrightApplied = true\n        end\n    else\n        if NexusState.fullBrightApplied then\n            NexusState.fullBrightApplied = false\n        end\n    end\nend\n\nruntimeEnv.NexusFrameConnection = RunService.RenderStepped:Connect(function(dt)\n    if not alive() then return end\n    pcall(updateFrameLogic, dt)\nend)\n\n-- ============================================================\n-- ===== PREPARE GLOBALS FOR THE CHUNKS =====\n-- ============================================================\n_G.RunService = RunService\n_G.LocalPlayer = LocalPlayer\n_G.VirtualUser = VirtualUser\n_G.UserInputService = UserInputService\n_G.Events = Events\n_G.MiscFlags = MiscFlags\n_G.alive = alive\n_G.runtimeEnv = runtimeEnv\n_G.Players = Players\n_G.Workspace = Workspace\n_G.Lighting = Lighting\n_G.NexusState = NexusState\n_G.Fishing = Fishing\n\n-- ===== LIVE ANTI-AFK (main chunk; fires only on real Idled, never steals controller) =====\ndo\n    local function nexusNudgeInput()\n        if Fishing and Fishing.Flags and not Fishing.Flags.AntiAFK then return end\n        local moving = false\n        pcall(function()\n            local char = LocalPlayer.Character\n            local hum = char and char:FindFirstChildOfClass(\"Humanoid\")\n            local md = hum and hum.MoveDirection\n            if md and (math.abs(md.X or 0) + math.abs(md.Z or 0) > 0.05) then moving = true end\n        end)\n        if moving then return end\n        pcall(function()\n            if Events and Events:FindFirstChild(\"AFK\") then\n                Events.AFK:FireServer()\n            end\n            if VirtualUser and workspace.CurrentCamera then\n                VirtualUser:Button2Down(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n                task.wait(0.2)\n                VirtualUser:Button2Up(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n            end\n        end)\n    end\n    pcall(function()\n        if runtimeEnv.AntiAFKConnection then runtimeEnv.AntiAFKConnection:Disconnect() end\n    end)\n    runtimeEnv.AntiAFKConnection = LocalPlayer.Idled:Connect(function()\n        nexusNudgeInput()\n    end)\nend\n\n-- ===== RUN THE EXTRA CHUNKS =====\nif _G.codetorun then loadstring(_G.codetorun)() end\nif _G.codes then loadstring(_G.codes)() end\n\n-- ===== SERVER HOP TAB =====\ndo\n    local ServerHopTab = Window:CreateTab(\"Server Hop\")\n    local Section = ServerHopTab:CreateSection(\"List Server Hop\")\n    NexusState.serverHopApiBase = NexusState.serverHopApiBase or \"http://103.28.35.190:8000\"\n    NexusState.serverHopApiKey = NexusState.serverHopApiKey or \"\"\n    NexusState.serverHopCategory = NexusState.serverHopCategory or \"Taoist\"\n    NexusState.serverHopWeather = NexusState.serverHopWeather or \"Thunderstorm\"\n    NexusState.serverHopBusy = false\n    NexusState.serverHopGeneration = 0\n    NexusState.serverHopRows = {}\n\n    local categories = {\n        \"Taoist\",\n        \"Maoshan\",\n        \"Spirit\",\n        \"Weather\",\n        \"Vermilion Birdblood\",\n        \"Black Tortoise Bloodline\",\n        \"Enzo\",\n        \"Nameless Octoparasite\",\n    }\n    local weatherOptions = {\n        \"Thunderstorm\",\n        \"Rainy\",\n        \"Windy\",\n        \"Snowy\",\n        \"Foggy\",\n        \"Blazing Sun\",\n    }\n    local statusHandle\n    local refresh\n    local lastHopAt = -math.huge\n\n    local function api(path, method, body)\n        local requestFn = (syn and syn.request) or http_request or request\n            or (http and http.request) or (fluxus and fluxus.request)\n        if type(requestFn) ~= \"function\" then return nil, \"HTTP unavailable\" end\n\n        local ok, response = pcall(requestFn, {\n            Url = NexusState.serverHopApiBase:gsub(\"/$\", \"\") .. path,\n            Method = method or \"GET\",\n            Timeout = 10,\n            Headers = {\n                [\"Content-Type\"] = \"application/json\",\n                [\"X-API-Key\"] = NexusState.serverHopApiKey or \"\",\n            },\n            Body = body,\n        })\n        if not ok or not response then return nil, \"Relay request failed\" end\n\n        local code = tonumber(response.StatusCode or response.Status)\n        if code and (code < 200 or code >= 300) then\n            return nil, \"Relay HTTP \" .. tostring(code)\n        end\n\n        local raw = response.Body or response.body\n        local decoded, data = pcall(function()\n            return Services.HttpService:JSONDecode(raw)\n        end)\n        if not decoded or type(data) ~= \"table\" then return nil, \"Invalid relay response\" end\n        return data\n    end\n\n    local function readCurrentWeather()\n        local result = \"Clear\"\n        pcall(function()\n            local info = MainGui and MainGui:FindFirstChild(\"Info\")\n            local details = info and info:FindFirstChild(\"Info\")\n            local weather = details and details:FindFirstChild(\"Weather\")\n            local value = weather and weather:FindFirstChild(\"Value\")\n            if value then\n                local raw = value:IsA(\"TextLabel\") and value.Text or value.Value\n                result = tostring(raw or \"Clear\")\n                    :gsub(\"Weather:%s*\", \"\")\n                    :gsub(\"^%s+\", \"\")\n                    :gsub(\"%s+$\", \"\")\n            end\n        end)\n        return result\n    end\n\n    local function scanLocalEventTags()\n        local found = {\n            taoist = false,\n            maoshan = false,\n            spirit = false,\n            vermilion = false,\n            tortoise = false,\n            enzo = false,\n            nameless = false,\n        }\n        local roots = {}\n        for _, name in ipairs({\"Ocean\", \"NPC\", \"Map\", \"Fishes\"}) do\n            local root = Workspace:FindFirstChild(name)\n            if root then roots[#roots + 1] = root end\n        end\n\n        local function readFlag(instance, name)\n            local value\n            pcall(function() value = instance:GetAttribute(name) end)\n            if value == true then return true end\n            if type(value) == \"number\" then return value > 0 end\n            local normalized = string.lower(tostring(value or \"\"))\n            return normalized == \"true\"\n                or normalized == \"active\"\n                or normalized == \"spawned\"\n                or normalized == \"appeared\"\n                or normalized == \"ready\"\n        end\n\n        local function hasActiveFlag(instance)\n            for _, name in ipairs({\n                \"InFight\", \"Active\", \"IsActive\", \"Spawned\", \"Appeared\",\n                \"Enabled\", \"CanAttack\", \"Ready\",\n            }) do\n                if readFlag(instance, name) then return true end\n            end\n            for _, name in ipairs({\"InFight\", \"Active\", \"IsActive\", \"Spawned\", \"Appeared\"}) do\n                local child\n                pcall(function() child = instance:FindFirstChild(name, true) end)\n                if child then\n                    local value\n                    pcall(function() value = child.Value end)\n                    if value == true or (type(value) == \"number\" and value > 0) then\n                        return true\n                    end\n                end\n            end\n            return false\n        end\n\n        local function hasLiveEvidence(instance, isBoss)\n            local isModel = false\n            local isPart = false\n            pcall(function()\n                isModel = instance:IsA(\"Model\")\n                isPart = instance:IsA(\"BasePart\")\n            end)\n            if not isModel and not isPart then return false end\n\n            local rootPart\n            pcall(function()\n                rootPart = instance:FindFirstChild(\"HumanoidRootPart\", true)\n                    or instance:FindFirstChildWhichIsA(\"BasePart\", true)\n            end)\n            if not rootPart then   IslandSection:CreateButton({\n                Name = v.name,\n                Callback = function()\n                    local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n                    if hrp then\n                        hrp.CFrame = CFrame.new(v.cframe.Position) + Vector3.new(0, 5, 0)\n                        NexusLib:Notify({ Title = \"Teleport\", Message = \"Teleported to \" .. v.name, Duration = 3 })\n                    end\n                end\n            })\n        end\n    end\n    -- ===== PLAYERS SECTION =====\n    do\n        local PlayerSection = TeleportTab:CreateSection(\"Players\", \"Right\")\n        \n        local selectedPlayer = nil\n        local playerDropdown = nil  -- Keep a reference to the dropdown\n        local playerList = {}\n        \n        -- List refresh helper\n        local function refreshPlayerList()\n            -- Read the player list\n            playerList = {}\n            for _, player in ipairs(Players:GetPlayers()) do\n                if player ~= LocalPlayer then\n                    table.insert(playerList, player.Name)\n                end\n            end\n            if #playerList == 0 then\n                table.insert(playerList, \"No other players\")\n                selectedPlayer = \"No other players\"\n            else\n                selectedPlayer = playerList[1]\n            end\n            \n            -- Remove the old dropdown if present\n            if playerDropdown and playerDropdown._frame then\n                pcall(function()\n                    playerDropdown._frame:Destroy()\n                end)\n                playerDropdown = nil\n            end\n            \n            -- Create the new dropdown\n            playerDropdown = PlayerSection:CreateDropdown({\n                Name = \"Select Player\",\n                Options = playerList,\n                Default = selectedPlayer,\n                Callback = function(value)\n                    selectedPlayer = value\n                end\n            })\n        end\n        \n        -- Create the dropdown for the first time\n        refreshPlayerList()\n        \n        -- Refresh List button\n        PlayerSection:CreateButton({\n            Name = \"Refresh List\",\n            Callback = function()\n                refreshPlayerList()\n                NexusLib:Notify({\n                    Title = \"Players\",\n                    Message = \"Player list refreshed! Found \" .. #playerList .. \" players.\",\n                    Duration = 2\n                })\n            end\n        })\n        \n        -- Teleport to Player button\n        PlayerSection:CreateButton({\n            Name = \"Teleport to Player\",\n            Callback = function()\n                if not selectedPlayer or selectedPlayer == \"No other players\" then\n                    NexusLib:Notify({ Title = \"Teleport\", Message = \"No valid player selected!\", Duration = 2 })\n                    return\n                end\n                \n                local targetPlayer = nil\n                for _, player in ipairs(Players:GetPlayers()) do\n                    if player.Name == selectedPlayer then\n                        targetPlayer = player\n                        break\n                    end\n                end\n                \n                if not targetPlayer then\n                    NexusLib:Notify({ Title = \"Teleport\", Message = \"Player not found! Try refreshing.\", Duration = 2 })\n                    return\n                end\n                \n                local character = targetPlayer.Character\n                if not character then\n                    NexusLib:Notify({ Title = \"Teleport\", Message = targetPlayer.Name .. \" has no character!\", Duration = 2 })\n                    return\n                end\n                \n                local hrp = character:FindFirstChild(\"HumanoidRootPart\")\n                if not hrp then\n                    NexusLib:Notify({ Title = \"Teleport\", Message = \"Cannot find HumanoidRootPart!\", Duration = 2 })\n                    return\n                end\n                \n                local myChar = LocalPlayer.Character\n                if not myChar then return end\n                local myHrp = myChar:FindFirstChild(\"HumanoidRootPart\")\n                if not myHrp then return end\n                \n                myHrp.CFrame = hrp.CFrame + Vector3.new(0, 3, 0)\n                \n                NexusLib:Notify({\n                    Title = \"Teleport\",\n                    Message = \"Teleported to \" .. targetPlayer.Name,\n                    Duration = 2\n                })\n            end\n        })\n    -- ===== SPECTATE PLAYER =====\n        local spectateEnabled = false\n        local spectateTarget = nil\n        local oldSubject = nil\n        local oldCameraType = nil\n        local espConnections = {}\n        \n        -- Start spectate\n        local function startSpectate()\n            if spectateEnabled then return end\n            \n            -- Find the first player other than yourself\n            local targetPlayer = nil\n            for _, player in ipairs(Players:GetPlayers()) do\n                if player ~= LocalPlayer then\n                    targetPlayer = player\n                    break\n                end\n            end\n            \n            if not targetPlayer then\n                NexusLib:Notify({ Title = \"Spectate\", Message = \"No other players to spectate!\", Duration = 2 })\n                if NexusState.spectateToggle then\n                    NexusState.spectateToggle:Set(false)\n                end\n                return\n            end\n            \n            -- Check whether the target has a character\n            if not targetPlayer.Character then\n                NexusLib:Notify({ Title = \"Spectate\", Message = targetPlayer.Name .. \" has no character!\", Duration = 2 })\n                if NexusState.spectateToggle then\n                    NexusState.spectateToggle:Set(false)\n                end\n                return\n            end\n            \n            local targetHrp = targetPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n            if not targetHrp then\n                NexusLib:Notify({ Title = \"Spectate\", Message = \"Cannot find HumanoidRootPart of \" .. targetPlayer.Name, Duration = 2 })\n                if NexusState.spectateToggle then\n                    NexusState.spectateToggle:Set(false)\n                end\n                return\n            end\n            \n            spectateEnabled = true\n            spectateTarget = targetPlayer\n            \n            local camera = workspace.CurrentCamera\n            oldSubject = camera.CameraSubject\n            oldCameraType = camera.CameraType\n            \n            -- Lock the camera onto the target\n            camera.CameraSubject = targetHrp\n            camera.CameraType = Enum.CameraType.Custom\n            \n            NexusLib:Notify({ Title = \"Spectate\", Message = \"Spectating \" .. targetPlayer.Name, Duration = 2 })\n        end\n        \n        -- Stop spectate\n        local function stopSpectate()\n            spectateEnabled = false\n            spectateTarget = nil\n            \n            -- Reset the camera back to the local player\n            pcall(function()\n                local camera = workspace.CurrentCamera\n                if oldSubject then\n                    camera.CameraSubject = oldSubject\n                    oldSubject = nil\n                end\n                if oldCameraType then\n                    camera.CameraType = oldCameraType\n                    oldCameraType = nil\n                end\n            end)\n            \n            NexusLib:Notify({ Title = \"Spectate\", Message = \"Stopped spectating\", Duration = 2 })\n        end\n        \n        -- Toggle Spectate Player\n        local spectateToggle = Cfg.register(PlayerSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Spectate Player\", {\n            Name = \"Spectate Player\",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    startSpectate()\n                else\n                    stopSpectate()\n                end\n            end\n        })), \"Toggle\", \"Spectate Player\", {\n            Name = \"Spectate Player\",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    startSpectate()\n                else\n                    stopSpectate()\n                end\n            end\n        })\n        \n        -- Persist the toggle in NexusState\n        NexusState.spectateToggle = spectateToggle\n        \n        -- Handle the target leaving or their character resetting\n        local function onTargetCharacterAdded()\n            if spectateEnabled and spectateTarget then\n                local char = spectateTarget.Character\n                if char then\n                    local hrp = char:FindFirstChild(\"HumanoidRootPart\")\n                    if hrp then\n                        workspace.CurrentCamera.CameraSubject = hrp\n                    end\n                end\n            end\n        end\n        \n        -- Listen for the target's character changing\n        local charAddedConn = nil\n        local playerRemovingConn = Players.PlayerRemoving:Connect(function(player)\n            if spectateEnabled and player == spectateTarget then\n                stopSpectate()\n                if NexusState.spectateToggle then\n                    NexusState.spectateToggle:Set(false)\n                end\n            end\n        end)\n        \n        -- While spectating, watch the target's CharacterAdded\n        local function monitorTarget()\n            if spectateEnabled and spectateTarget then\n                if charAddedConn then charAddedConn:Disconnect() end\n                charAddedConn = spectateTarget.CharacterAdded:Connect(function()\n                    task.wait(0.5)\n                    onTargetCharacterAdded()\n                end)\n            else\n                if charAddedConn then\n                    charAddedConn:Disconnect()\n                    charAddedConn = nil\n                end\n            end\n        end\n        \n        -- Wrap startSpectate to attach the monitor\n        local originalStart = startSpectate\n        startSpectate = function()\n            originalStart()\n            monitorTarget()\n        end\n        \n        -- Wrap stopSpectate to clean up\n        local originalStop = stopSpectate\n        stopSpectate = function()\n            originalStop()\n            if charAddedConn then\n                charAddedConn:Disconnect()\n                charAddedConn = nil\n            end\n        end\n        \n        table.insert(espConnections, { conn = playerRemovingConn })\n    end\n    -- ===== NPCs SECTION =====\n    do\n        local NpcSection = TeleportTab:CreateSection(\"NPCs\", \"Right\")\n        \n        -- NPC list helper (models parented to a Folder under workspace.NPC.Function)\n        local function getNpcList()\n            local npcs = {}\n            local funcFolder = workspace:FindFirstChild(\"NPC\") and workspace.NPC:FindFirstChild(\"Function\")\n            if not funcFolder then return npcs end\n            \n            for _, child in ipairs(funcFolder:GetDescendants()) do\n                if typeof(child) == \"Instance\" and child:IsA(\"Model\") and child.Parent and typeof(child.Parent) == \"Instance\" and child.Parent:IsA(\"Folder\") then\n                    table.insert(npcs, child.Name)\n                end\n            end\n            return npcs\n        end\n        \n        local npcList = getNpcList()\n        if #npcList == 0 then\n            table.insert(npcList, \"No NPCs found\")\n        end\n        \n        local selectedNpc = npcList[1]\n        \n        -- Create the dropdown\n        local ",
